insert into guides (id,content) values ('brake-pads-r32',$j${"id": "brake-pads-r32", "title": "Brake pads (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "brake-hero", "alsoFits": "Mk6 Golf R (same 345/310 brakes); B6 Passat and CC 345mm cars share the front", "category": "Brakes", "kind": "repair", "variants": {"question": "Front or rear?", "hint": "Different calipers, different tools. Front pistons push back; rear pistons have to be screwed back.", "options": [{"id": "front", "label": "Front pads", "when": "7mm hex guide bolts, 345mm rotor, wear sensor"}, {"id": "rear", "label": "Rear pads", "when": "13mm guide bolts, 310mm rotor, piston screws in"}]}, "glance": {"timeFirst": "1–1.5 hr", "timeRepeat": "40 min", "difficulty": 2, "cost": "$50–150 per axle", "risk": "Car on stands · brake fluid · never touch friction surfaces with greasy hands", "why": "Pads are the part of the brake that's designed to wear away. On the GTI the fronts do most of the work and go first; the rears last longer but bind up more. It's the most common job on any car, and one of the most satisfying to do yourself. The R32 runs bigger brakes than the GTI: 345 mm fronts and 310 mm rears, so the parts are different and the procedure is the same.", "note": "Vendor and forum times agree: about an hour an axle, longer the first time you meet a seized rotor screw."}, "heroCap": "Caliper (piston side) slides on two guide pins in the carrier. Two small bolts free the caliper; two big ones free the carrier. For pads only, the carrier stays.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Front pads: typically 30,000–50,000 miles", "only": ["front"]}, {"text": "Rear pads: typically 50,000–70,000 miles", "only": ["rear"]}], "earliest": "Much sooner with track use or a sticking caliper slide pin", "detail": "The wear sensor on the front inner pad lights the dash when the pad reaches about 3mm. Rears have no sensor; look through the wheel or pull it. A pad worn to the backing plate scores the rotor and turns a pad job into a rotor job.", "factors": ["Spirited or track driving", "Sticking guide pins (uneven wear)", "City stop-and-go", "A stuck parking brake (rears)"], "inspect": ["Every tire rotation: pad thickness through the wheel spokes"], "confidence": {"level": "community", "n": 4, "note": "Owner reports and vendor notes; no factory mileage exists because it depends on the driver."}}, "should": {"yesIf": ["Pad warning light on the dash (front)", "Less than about 3mm of friction material left", "Squeal at low speed that goes away when you brake harder (wear indicator)", "Grinding: you're already into the rotor"], "codes": [], "notes": ["Pads and rotors: if the rotor has a lip at the edge you can catch a fingernail on, or the pads wore unevenly, do rotors too (that's the next guide). New pads on a worn rotor bed in badly and feel soft.", "Both sides of an axle, always, with the same pad compound.", "R32 sizes: 345×30 mm front, 310×22 mm rear. Rotors and pads for a GTI do not fit; the torque values and the caliper design are the same PQ35 hardware."], "confidence": {"level": "high", "n": 4, "note": "Standard practice; consistent across sources."}}, "parts": [{"tier": "oe", "name": "Front pad set, Genuine/OEM (TRW or Textar)", "pn": "1K0 698 151 (345mm; confirm by VIN)", "note": "Includes wear sensor on most kits", "price": "$60–90", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Rear pad set, Genuine/OEM", "pn": "1K0 698 451 (310mm; confirm by VIN)", "note": "", "price": "$40–70", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Rear caliper guide-pin bolts, M8x22 (×4)", "pn": "self-locking", "note": "Replace every time (ECS, Bentley)", "price": "$6", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Front pad wear sensor", "pn": "if not in the kit", "note": "The old one is usually cut through", "price": "$10", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Brake caliper grease, brake cleaner", "pn": "—", "note": "Silicone or ceramic paste for pad ears and guide pins", "price": "$12", "links": []}], "aftermarket": [{"name": "Ferodo DS2500 / Hawk HPS", "note": "Street-performance compounds: more bite, more dust, fine cold. The forum default for a spirited daily.", "price": "$120–180", "signal": "Spirited-daily pick", "links": []}, {"name": "EBC Redstuff / Yellowstuff", "note": "Red for low dust street; Yellow for track days but noisy on the street.", "price": "$100–160", "signal": "Know which colour you want", "links": []}, {"name": "Akebono Euro ceramic", "note": "Quiet, very low dust, slightly less bite than OE. Popular for a clean-wheels daily.", "price": "$60–90", "signal": "Low-dust pick", "links": []}], "tools": [{"name": "Jack + stands, 17mm for lugs"}, {"name": "7mm hex bit (front caliper guide bolts), flat screwdriver for the spring clip", "only": ["front"]}, {"name": "13mm socket + 15mm wrench (rear caliper bolts), rear piston retractor tool (cube or wind-back kit)", "only": ["rear"]}, {"name": "Large C-clamp or piston spreader (front)", "only": ["front"]}, {"name": "Wire brush, brake cleaner, bungee or wire to hang the caliper, torque wrench to 35 Nm"}], "before": ["Loosen the reservoir cap and remove a little fluid if it's near MAX; pushing pistons back raises the level.", "Never let the caliper hang by its hose.", "Both sides of the axle in one session."], "steps": [{"n": 1, "title": "Wheel off, look", "blocks": [{"t": "text", "b": "Lugs loose on the ground, raise the axle, stands under the body, wheel off. Look at the pad through the caliper window and at the rotor edge for a lip."}]}, {"n": 2, "title": "Free the caliper", "blocks": [{"t": "text", "b": "Pry the big spring clip off the caliper face with a screwdriver. Unplug the wear-sensor wire from its clip. Pull the two rubber caps off the back of the caliper and remove the two 7mm hex guide bolts. Lift the caliper off the carrier and hang it from the spring with a bungee.", "only": ["front"]}, {"t": "text", "b": "Pry the spring clip off. Hold each guide pin with a 15mm wrench and remove the 13mm bolt; discard the bolts. Lift the caliper off and hang it. The parking-brake cable stays connected.", "only": ["rear"]}, {"t": "ill", "id": "brake-hero", "cap": "Guide bolts (small) free the caliper; carrier bolts (large) stay put for a pad job."}]}, {"n": 3, "title": "Old pads out, clean everything", "blocks": [{"t": "text", "b": "Pull the pads out of the carrier (front: the inner pad clips into the piston). Wire-brush the carrier's pad seats until the new pads slide freely in them; a pad that binds here is what causes uneven wear. Check the guide-pin boots and that the pins slide."}]}, {"n": 4, "title": "Retract the piston", "caution": true, "blocks": [{"t": "text", "b": "Put the old inner pad across the piston and squeeze it back with a C-clamp, slowly, watching the reservoir level.", "only": ["front"]}, {"t": "text", "b": "Rear pistons screw in. Use the retractor tool to turn the piston clockwise while pushing; do not just squeeze it or you'll wreck the parking-brake mechanism inside. Stop when it's flush and line up one of the piston's notches with the nub on the new inner pad.", "only": ["rear"]}, {"t": "warn", "b": "Slow. A piston forced back too fast can pop the master-cylinder seals or overflow the reservoir onto the paint."}]}, {"n": 5, "title": "New pads in", "blocks": [{"t": "text", "b": "Thin smear of caliper grease on the pad ears and the back of the pads (never the friction face). Outer pad into the carrier, inner pad clipped into the piston (front) or seated with its nub in the piston notch (rear). New wear sensor clipped into the inner pad and routed the same way as the old one."}]}, {"n": 6, "title": "Caliper back on", "blocks": [{"t": "text", "b": "Lower the caliper over the pads, grease and fit the guide bolts, and torque them. Refit the rubber caps and the spring clip.", "only": ["front", "rear"]}, {"t": "torque", "label": "Front caliper guide bolts (7mm hex)", "nm": 28, "alt": [35], "c": {"level": "varies", "n": 3, "note": "28 Nm (Bentley), 30 and 35 Nm in forum tables for the same caliper. Any of these is fine; they're small bolts, don't overdo them."}, "only": ["front"]}, {"t": "torque", "label": "Rear caliper bolts (M8, new, 13mm)", "nm": 35, "c": {"level": "high", "n": 3, "note": "ECS, Bentley and forum agree: 35 Nm, new self-locking bolts."}, "only": ["rear"]}]}, {"n": 7, "title": "Other side, then pump the pedal", "blocks": [{"t": "text", "b": "Repeat on the other side. Wheels on (120 Nm). Before you drive: pump the brake pedal until it's firm so the pistons take up the gap. Check the reservoir level and cap it."}]}, {"n": 8, "title": "Bed them in", "blocks": [{"t": "text", "b": "A few gentle stops, then five or six firm stops from 40 mph without coming to a complete halt, then a few minutes of driving without braking to cool. Skip this and the pads glaze and squeal for weeks."}]}], "alsoReplace": [{"name": "Rotors", "why": "If there's a lip or scoring, the extra work is two carrier bolts and a set screw. See the rotor guide."}, {"name": "Brake fluid", "why": "If it's dark or over two years old, you already have the wheels off. See the flush guide."}], "check": {"tab": "Read the wear", "title": "Reading the old pads", "illId": "brake-hero", "illCap": "Uneven wear is a caliper problem, not a pad problem.", "rows": [{"see": "Both pads worn evenly, 2–3mm left", "means": "Normal end of life.", "do": "Replace pads."}, {"see": "Inner pad far more worn than outer", "means": "Guide pins sticking or piston sluggish.", "do": "Clean and grease pins; if the piston won't retract smoothly, rebuild or replace the caliper."}, {"see": "Tapered wear across one pad", "means": "Carrier pad seats corroded; pad can't float.", "do": "Wire-brush the carrier seats hard, or replace the carrier."}, {"see": "Pad worn to metal, rotor scored", "means": "Way past due.", "do": "Pads and rotors."}], "c": {"level": "community", "n": 3, "note": "Standard diagnosis; consistent across sources."}}, "aftercare": ["Bed in properly.", "Re-check guide bolt torque after 100 miles if you had to fight the caliper on.", "Squeal after a week: pads not bedded, or the anti-rattle spring is off."], "disagreements": [{"topic": "Front guide-bolt torque", "pos": "28, 30 and 35 Nm across sources for the same caliper.", "call": "28–35. Not a critical value."}, {"topic": "Reuse caliper bolts?", "pos": "Rear bolts are self-locking and every source says replace; front OE pads come with new bolts and thread-locker.", "call": "New on the rear; front, reuse with blue thread-locker if the kit didn't include them."}], "sources": ["ECS Tuning Mk5 GTI rear pads and rotors procedure", "myturbodiesel Mk5 Golf torque thread (Bentley)", "Golfmk7 and Golfmk6 brake torque threads", "Audizine PQ35 rear caliper thread"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('brake-rotors-r32',$j${"id": "brake-rotors-r32", "title": "Brake rotors (and pads) (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "brake-hero", "alsoFits": "Mk6 Golf R (same 345/310 brakes); B6 Passat and CC 345mm cars share the front", "category": "Brakes", "kind": "repair", "variants": {"question": "Front or rear?", "hint": "Front rotors are 312mm and the carrier bolts are big and tight. Rear rotors are 286mm and the carrier bolts are stretch bolts you replace.", "options": [{"id": "front", "label": "Front rotors", "when": "Carrier bolts 190–200 Nm, reuse"}, {"id": "rear", "label": "Rear rotors", "when": "Carrier bolts 90 Nm + 90°, replace"}]}, "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2.5, "cost": "$120–300 per axle with pads", "risk": "Very tight carrier bolts · seized set screw · heavy front rotors", "why": "Rotors wear a fraction of a millimetre per pad set and warp if they overheat. When there's a lip at the edge, grooves you can feel, or a shudder under braking, they're done. Always with new pads: a fresh pad on a worn rotor never beds right. The R32 runs bigger brakes than the GTI: 345 mm fronts and 310 mm rears, so the parts are different and the procedure is the same.", "note": "The set screw is the wildcard. Plan for it to strip and have a drill ready."}, "heroCap": "Carrier off (two big bolts), set screw out, rotor off the hub. Clean the hub face before the new rotor goes on or you'll build in a wobble.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Front rotors: typically every second pad set, 60,000–100,000 miles", "only": ["front"]}, {"text": "Rear rotors: typically 80,000–120,000 miles, often rust-limited rather than wear-limited", "only": ["rear"]}], "earliest": "Sooner if pads were run to metal, or on track cars", "detail": "Minimum thickness is stamped on the rotor hat (MIN TH). Measure with a caliper gauge away from the lip. Salt-belt cars usually lose rear rotors to rust pitting long before they're thin.", "factors": ["Pads run to the backing plate", "Track days", "Road salt (rears especially)", "Sticking caliper"], "inspect": ["Every pad change: thickness against the MIN TH stamp, and run a fingernail across the face"], "confidence": {"level": "community", "n": 4, "note": "Owner practice; the MIN TH stamp is the only hard number."}}, "should": {"yesIf": ["Lip at the rotor edge you can catch a nail on", "Shudder or pulsing pedal under braking", "Grooves or heat spots on the face", "Below the MIN TH stamped on the hat", "Pads wore to metal"], "codes": [], "notes": ["Slotted or drilled? On a street car neither does much beyond looks, and drilled rotors can crack from the holes with track heat. Plain or slotted blanks from a good maker are the value pick.", "R32 sizes: 345×30 mm front, 310×22 mm rear. Rotors and pads for a GTI do not fit; the torque values and the caliper design are the same PQ35 hardware."], "confidence": {"level": "high", "n": 4, "note": "Standard practice; consistent."}}, "parts": [{"tier": "oe", "name": "Front rotors, 345mm (pair)", "pn": "1K0 615 301 M (345×30; confirm by VIN)", "note": "Zimmermann, ATE, Brembo blanks are OE-quality", "price": "$90–160", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Rear rotors, 310mm (pair)", "pn": "1K0 615 601 M (310×22; confirm by VIN)", "note": "", "price": "$70–120", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Pads for the same axle", "pn": "see the pads guide", "note": "Always with rotors", "price": "$40–150", "links": []}, {"tier": "oe", "name": "Rotor set screws, T30 (×2)", "pn": "N 906 218 01", "note": "You will destroy at least one", "price": "$3", "links": []}, {"tier": "oe", "name": "Rear carrier bolts (×4)", "pn": "M12, torque-to-yield", "note": "Replace (ECS, Bentley, forums)", "price": "$12", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Rear caliper guide-pin bolts (×4)", "pn": "M8x22 self-locking", "note": "Replace", "price": "$6", "links": [], "only": ["rear"]}], "aftermarket": [{"name": "Zimmermann coated / ATE PremiumOne (pairs with pads)", "note": "OE-spec blanks with an anti-rust coating on the hat and edges. The sensible upgrade.", "price": "$100–180", "signal": "Value pick", "links": []}, {"name": "StopTech / Brembo slotted", "note": "Slots help with pad gassing on track and look the part. Slightly more pad wear.", "price": "$180–300", "signal": "Spirited pick", "links": []}, {"name": "R32/Golf R 345mm as a GTI upgrade", "note": "The R32's brakes are the classic GTI big-brake swap. If you're reading this on a GTI: you need the R32 carriers too.", "price": "—", "signal": "Note", "links": []}], "tools": [{"name": "Jack + stands, 17mm for lugs, breaker bar"}, {"name": "21mm socket for the front carrier bolts (½\" drive, they are very tight); 7mm hex for guide bolts; C-clamp", "only": ["front"]}, {"name": "18mm or 21mm for the rear carrier bolts (check yours); 13mm + 15mm for caliper bolts; rear piston retractor", "only": ["rear"]}, {"name": "T30 Torx and an impact driver for the set screw; drill and bits for when it strips"}, {"name": "Wire brush or Roloc disc for the hub face; torque wrench to 200 Nm; angle gauge (rear)"}], "before": ["Penetrating oil on the set screw and carrier bolts while you get the wheel off.", "Front rotors are heavy; don't drop one on a toe or the carrier's threads.", "Reservoir cap loose, level checked."], "steps": [{"n": 1, "title": "Wheel off, caliper off", "blocks": [{"t": "text", "b": "Follow the pads guide to free the caliper and hang it (spring clip, sensor wire, guide bolts). Pull the old pads."}]}, {"n": 2, "title": "Carrier off", "caution": true, "blocks": [{"t": "text", "b": "Two big bolts behind the hub hold the carrier to the knuckle. Breaker bar, steady pull. Lift the carrier away.", "only": ["front", "rear"]}, {"t": "warn", "b": "Rear carrier bolts are torque-to-yield: they stretch once and are done. Throw them away and fit new ones on reassembly, or they can back out.", "only": ["rear"]}, {"t": "warn", "b": "Front carrier bolts are torqued to 190–200 Nm and can be rusted in. Keep the breaker bar in line and your knuckles clear when it lets go.", "only": ["front"]}]}, {"n": 3, "title": "Set screw and rotor", "timeSink": true, "blocks": [{"t": "text", "b": "T30 impact driver on the set screw: a few sharp hits, then turn. If it rounds, drill the head off; the rotor comes off and the stub unscrews with pliers. Then the rotor: a few whacks with a hammer on the hat between the studs, or a bolt threaded into the hub's puller hole, breaks the rust bond."}, {"t": "ill", "id": "brake-hero", "cap": "Set screw is only there to hold the rotor while the wheel is off. Snug, never tight."}]}, {"n": 4, "title": "Clean the hub face", "blocks": [{"t": "text", "b": "Wire brush or Roloc disc the hub face back to bare metal, especially the raised ring the rotor sits on. Any rust flake left behind is runout you'll feel as a shudder in a month. Wipe the new rotor's face with brake cleaner to remove the shipping oil."}]}, {"n": 5, "title": "New rotor and carrier", "blocks": [{"t": "text", "b": "Rotor on, set screw in snug (about 4 Nm; just enough to hold it). Carrier over the rotor, bolts in.", "only": ["front", "rear"]}, {"t": "torque", "label": "Front carrier bolts (×2, reuse)", "nm": 190, "alt": [200], "c": {"level": "varies", "n": 3, "note": "190 Nm (Bentley) vs 200 Nm (forum tables). Either; it's a big bolt and both are in range."}, "only": ["front"]}, {"t": "torque", "label": "Rear carrier bolts (×2, NEW)", "nm": 90, "c": {"level": "high", "n": 3, "note": "90 Nm then a further 90° turn, new bolts every time. ECS, Bentley and forums agree."}, "note": "+90° turn", "only": ["rear"]}]}, {"n": 6, "title": "Pads and caliper", "blocks": [{"t": "text", "b": "Continue with the pads guide from 'Retract the piston': new pads, caliper on, guide bolts torqued, clip and sensor back."}]}, {"n": 7, "title": "Other side, pump, bed in", "blocks": [{"t": "text", "b": "Repeat. Wheels on at 120 Nm. Pump the pedal firm before moving. Bed in: several firm stops from 40 mph, then cool. New rotors and pads need this more than pads alone."}]}], "alsoReplace": [{"name": "Wheel bearing check", "why": "Hub is exposed. Spin it and feel for roughness; a grumble now is a bearing job later."}, {"name": "Brake fluid flush", "why": "Wheels are off; see the flush guide."}, {"name": "Rear caliper parking-brake return spring", "why": "If the lever is sluggish, the caliper is on its way to sticking.", "only": ["rear"]}], "check": {"tab": "Read the rotor", "title": "Reading the old rotor", "illId": "brake-hero", "illCap": "A lip means wear; blue spots mean heat; rust ring means the pad isn't contacting.", "rows": [{"see": "Even wear, small lip, above MIN TH", "means": "Serviceable.", "do": "Could reuse with new pads, but bedding is worse. Most replace."}, {"see": "Grooves, blue heat spots, shudder", "means": "Overheated or run with worn pads.", "do": "Replace. Check caliper function."}, {"see": "Heavy rust pitting on the outer inch (rears)", "means": "Pad isn't sweeping the whole face; typical salt-belt rear.", "do": "Replace rotor and pads; check the caliper slides."}], "c": {"level": "community", "n": 3, "note": "Standard diagnosis."}}, "aftercare": ["Bed in.", "Shudder after new rotors: hub face wasn't clean, or lug bolts were tightened in a star pattern by impact. Re-torque by hand.", "Re-check carrier bolts after 100 miles."], "disagreements": [{"topic": "Front carrier torque", "pos": "190 vs 200 Nm.", "call": "190–200."}, {"topic": "Drilled rotors", "pos": "Look good; some forum voices swear by them.", "call": "Slotted or plain for anything that sees heat."}], "sources": ["ECS Tuning Mk5 GTI rear pads and rotors procedure", "myturbodiesel Bentley torque thread", "Golfmk7 / Golfmk6 torque threads", "Audizine PQ35 caliper thread"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('plugs-r32',$j${"id": "plugs-r32", "title": "Spark plugs & coil packs (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "ignition-hero", "alsoFits": "3.2 VR6 BUB in the Mk5 R32, A3 3.2, TT 3.2", "category": "Engine", "kind": "repair", "variants": null, "glance": {"timeFirst": "1 hr", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$60–90 plugs · $150–250 coils", "risk": "Cross-threading a plug · dropping debris in the plug well", "why": "Six plugs, six coils, all on top of the engine under the cover. The VR6's narrow-angle layout means the plugs are deep and the coils are long; otherwise it's the same twenty-minutes-per-cylinder job as any modern VW.", "note": "Plug and coil part numbers from R32 kit listings; procedure is the standard VW pull-the-coil job."}, "heroCap": "Six coils in a staggered row on the VR6's valve cover, plugs deep below. Unplug, pull straight up, plug out on a long 5/8\" socket.", "lifespan": {"title": "When to expect it", "headline": ["Plugs: every 60,000 miles (iridium); coils when they fail"], "earliest": "Copper race plugs (BKR7E) need changing every 12,000–15,000", "detail": "Iridium plugs go a long way on this engine. A tired coil shows as a misfire on one cylinder under load, especially damp mornings; the VR6's rear cylinders (4–6) live hotter and go first.", "factors": ["Tune", "Oil in the plug wells from a leaking valve cover gasket (kills coils)", "Wrong gap for the boost level"], "inspect": ["Any misfire code: pull the coil on that cylinder and swap it with a neighbour. If the code follows the coil, it's the coil."], "confidence": {"level": "community", "n": 4, "note": "Owner practice and vendor kit notes; the factory table wasn't fetched this pass."}}, "should": {"yesIf": ["Misfire under load, worse cold and damp", "Misfire code for one cylinder (P0301–P0306)", "60k since the last plugs, or unknown"], "codes": ["P0300", "P0301", "P0302", "P0303", "P0304", "P0305", "P0306"], "notes": ["Plugs: NGK IZKR7B (iridium) is the common R32 fitment; pre-gapped, don't adjust an iridium tip. Confirm against your parts source.", "Coils: 022 905 715 B (D is the later revision), six of them. Replace as a set once one fails; they're the same age."], "confidence": {"level": "high", "n": 4, "note": "Plug families, gaps and coil equivalence agree across a parts specialist's listing and multiple forum threads."}}, "parts": [{"tier": "oe", "name": "Spark plugs (×6), NGK IZKR7B", "pn": "NGK 6994", "note": "Iridium", "price": "$60–90", "links": []}, {"tier": "oe", "name": "Ignition coils (×6)", "pn": "022 905 715 B / D", "note": "Set", "price": "$150–250", "links": []}, {"tier": "oe", "name": "Dielectric grease", "pn": "—", "note": "", "price": "$8", "links": []}], "aftermarket": [{"name": "OEM+ coil sets (Bosch / Beru)", "note": "Same parts, maker's box.", "price": "$120–200", "signal": "Value", "links": []}], "tools": [{"name": "5/8\" (16mm) thin-wall plug socket on a long extension; 3/8\" ratchet"}, {"name": "Torque wrench to 30 Nm; coil puller or firm grip; small screwdriver for connector locks"}], "before": ["Engine cold. Plug threads in a hot aluminium head strip easily.", "Blow or vacuum the wells out before the plugs come out so nothing drops into the cylinder.", "Do one cylinder at a time so nothing gets mixed up."], "steps": [{"n": 1, "title": "Cover off, unplug the coils", "blocks": [{"t": "text", "b": "Engine cover off. Six coils in two staggered rows on the valve cover. Release each connector's lock and unplug."}]}, {"n": 2, "title": "Pull the coils", "blocks": [{"t": "text", "b": "Grip each coil and pull straight up; they're long and a friction fit. Note position (1–6, front to back). Oil on a coil means the cover gasket is leaking."}, {"t": "ill", "id": "ignition-hero", "cap": "Same idea as the four-cylinder drawing, six times. Plugs are deeper on the VR6."}]}, {"n": 3, "title": "Plugs out", "blocks": [{"t": "text", "b": "Blow the wells clear. Long extension, 5/8\" plug socket, break each plug loose and spin it out. Read them (table below)."}]}, {"n": 4, "title": "New plugs in", "caution": true, "blocks": [{"t": "text", "b": "Check the gap with a wire gauge without touching the iridium tip. Thread each plug in by hand on the socket until it seats, then torque."}, {"t": "torque", "label": "Spark plugs", "nm": 25, "alt": [30], "c": {"level": "varies", "n": 2, "note": "25–30 Nm from kit sheets; no factory figure confirmed this pass."}}, {"t": "warn", "b": "Deep wells and an aluminium head: hand-start every plug."}]}, {"n": 5, "title": "Coils in, drive", "blocks": [{"t": "text", "b": "Grease inside each boot, coils down until they seat, connectors on until they click, cover on. Full-throttle pull once warm; the stumble should be gone."}]}], "alsoReplace": [{"name": "Valve cover gasket", "why": "Oil in the plug wells kills coils. If the wells are wet, the gasket is the cause and it's a one-hour job."}, {"name": "PCV valve", "why": "Rough idle blamed on plugs is often the PCV. Same access."}], "check": {"tab": "Read the plugs", "title": "Reading the old plugs", "illId": "ignition-hero", "illCap": "Tan is right. Everything else is a clue.", "rows": [{"see": "Light tan to grey electrode, no deposits", "means": "Healthy engine, plug simply aged.", "do": "Replace, same type."}, {"see": "Black, sooty and dry", "means": "Rich, or the plug is too cold for the car, or lots of idling.", "do": "Check gap and heat range; if you fitted BKR8s on a Stage 1, that's why."}, {"see": "Oily, wet", "means": "Oil in the well from the cover gasket, or oil past the rings/PCV.", "do": "Gasket first; new coil on that cylinder."}, {"see": "White, blistered, tiny beads on the electrode", "means": "Too hot: lean, too much boost, or the plug is too hot a range.", "do": "Colder plug and a look at the tune before you damage a piston."}], "c": {"level": "community", "n": 3, "note": "Standard plug reading; consistent with forum experience on this engine."}}, "aftercare": ["Note mileage and plug type in the glovebox.", "Misfire returns on one cylinder: swap coils between cylinders and see if it moves."], "disagreements": [{"topic": "Plug torque", "pos": "25 vs 30 Nm.", "call": "25–30, flagged."}], "sources": ["VAGPARTS R32 coil and plug kit listing", "USP Motorsports R32 ignition catalog", "Standard VW coil-on-plug procedure (Pelican Mk5 article)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('air-filter-r32',$j${"id": "air-filter-r32", "title": "Engine air filter (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "alsoFits": "Mk5 R32 only (A3/TT 3.2 use different boxes)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "20 min", "timeRepeat": "10 min", "difficulty": 1, "cost": "$15–30", "risk": "None worth mentioning", "why": "The R32's airbox is a separate box at the front-left of the bay feeding the VR6's intake pipe. Lid off, filter out, ten minutes.", "note": "Same corner of the bay as the TSI drawing; fastener count differs by year, so count yours."}, "heroCap": "Side-mounted airbox at the front-left; lid screws around the edge, MAF sensor in the outlet.", "lifespan": {"title": "When to expect it", "headline": ["Inspect yearly; owners replace around every 20,000–40,000 miles"], "earliest": null, "detail": "A paper filter fails gradually. Hold it up to the light: if you can't see light through the pleats, or there's grit and leaves in the airbox, change it. Dusty roads and a lot of highway bugs shorten it.", "factors": ["Dusty or gravel roads", "Unknown history", "Rodent activity in the engine bay (check the snorkel)"], "inspect": ["Every oil change: pull the cover and look. It's two screws."], "confidence": {"level": "single", "n": 1, "note": "Factory interval not confirmed in this pass. Owner practice and vendor advice only."}}, "should": {"yesIf": ["You don't know when it was last done", "Filter looks grey, or you can't see light through it", "Debris in the airbox", "Every year or so regardless"], "codes": [], "notes": ["Stock paper filter versus an oiled cotton cone: the forums are clear that the stock box pulls cool air from the grille and the paper element isn't a restriction on a stock or Stage 1 car. Oiled filters can also foul the mass-airflow sensor. Stay paper unless you're going to a full intake (that's a separate guide)."], "confidence": {"level": "high", "n": 3, "note": "Vendor write-ups and forum consensus agree."}}, "parts": [{"tier": "oe", "name": "Engine air filter, R32", "pn": "1K0 129 620 (R32 variant; confirm by VIN)", "note": "Not the GTI filter", "price": "$20–35", "links": []}], "aftermarket": [{"name": "Drop-in cotton panel (K&N, aFe)", "note": "Fits the stock box. Slight airflow gain on paper, real risk of oil on the MAF sensor if over-oiled, and no cold-air benefit. Forums are lukewarm.", "price": "$50–70", "signal": "Community verdict: stay paper", "links": []}], "tools": [{"name": "T25 Torx"}, {"name": "Pliers for the breather tube clip; shop vac or rag"}], "before": ["Engine off and cool enough to lean over.", "Have the new filter out of the box so you can compare it to the old one."], "steps": [{"n": 1, "title": "Find the box", "blocks": [{"t": "text", "b": "Driver's side, front, behind the plastic intake duct that runs from the grille. The lid has screws around its edge; the MAF sensor sits in the outlet tube at the back."}, {"t": "ill", "id": "airbox-tsi", "cap": "The R32 box sits in the same corner as the TSI's. Count your lid screws; they're captive."}]}, {"n": 2, "title": "Loosen the lid screws", "blocks": [{"t": "text", "b": "Six T25 screws around the lid. They're captive: loosen them until they spin free, don't try to pull them out. Two more T25s at the back where the tube before the MAF joins the box; loosen those the same way."}]}, {"n": 3, "title": "Breather tube off", "blocks": [{"t": "text", "b": "The small breather tube at the front of the box: squeeze its sides and pull. It's stiff the first time. Cars with secondary air injection also have an SAI hose clipped to the box; unclip it."}]}, {"n": 4, "title": "Lid off, filter out", "blocks": [{"t": "text", "b": "Lift the lid clear. The panel filter sits in the lower half; lift it out and look at it (table below). Vacuum the box."}]}, {"n": 5, "title": "New filter, lid on", "blocks": [{"t": "text", "b": "New filter with its rubber edge seated all round. Lid on, snug the eight screws (plastic, don't crank), breather tube and SAI hose back. Start it and listen for hiss at the outlet tube."}]}], "alsoReplace": [{"name": "Cabin air filter", "why": "Same trip to the parts store, same 'nobody ever changed it' energy. It's behind the glovebox and takes ten minutes."}], "check": {"tab": "Read the filter", "title": "Reading your old filter", "illId": "airbox", "illCap": "Light through the pleats is the test.", "rows": [{"see": "Off-white, light passes through easily", "means": "Fine.", "do": "Put it back or replace if it's cheap and you're already here."}, {"see": "Grey, light passes with effort", "means": "Doing its job; near the end.", "do": "Replace."}, {"see": "Black, blocked, or debris/rodent nesting in the box", "means": "Restricting airflow; the previous owner never did this.", "do": "Replace, vacuum the box, check the snorkel and inlet pipe for debris."}], "c": {"level": "community", "n": 3, "note": "Standard practice; consistent across sources."}}, "aftercare": ["Note the mileage somewhere you'll find it.", "If you ever see oil residue on the MAF sensor after switching to an oiled filter, clean it with MAF cleaner and go back to paper."], "disagreements": [{"topic": "Interval", "pos": "FCP says 30–40k; owners inspect yearly.", "call": "Inspect at every oil change; replace when it fails the light test."}], "sources": ["R32 owner threads on the airbox", "Filter listings by VIN"], "embeds": [], "heroId": "airbox-tsi"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('haldex-service',$j${"id": "haldex-service", "title": "Haldex (4Motion) fluid & filter service", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "haldex-hero", "alsoFits": "Gen 2 Haldex cars: Mk5 R32, Audi A3 8P quattro 3.2, TT 8J quattro (rear diff prefix 0AV)", "category": "Drivetrain", "kind": "repair", "glance": {"timeFirst": "1 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$60–90 (oil + filter)", "risk": "Small plugs in soft aluminium · easy to round the hex", "why": "The Haldex coupling is the clutch pack that sends torque to the rear axle when the fronts slip. It runs in its own oil with a pump and a filter, and neglected oil is what kills the pump and glazes the clutches. Every R32 guide says the same thing: do it every 40k, and do it on purchase if there are no records.", "note": "Two forum DIYs and two vendor articles agree on the procedure; they differ on interval, recorded below."}, "heroCap": "Under the rear of the car: propshaft → Haldex coupling (its own oil, pump and filter) → rear differential (gear oil). Two units, two oils, plugs on each.", "lifespan": {"title": "When to expect it", "headline": ["Every 40,000 miles for oil and filter, or every 20,000 for oil if you drive it hard"], "earliest": "Immediately on a used car without records", "detail": "The system engages only when it needs to, so a tired Haldex gives no warning until the pump fails or the AWD light comes on. Dark, burnt-smelling oil is the sign you were late. The filter starves the pump when it clogs.", "factors": ["Track or launch use", "Towing (rare on an R32)", "Unknown history"], "inspect": ["Nothing to inspect from outside; keep the interval"], "confidence": {"level": "high", "n": 4, "note": "Interval and consequences agree across ECS, eEuroparts and owner DIYs."}}, "should": {"yesIf": ["40k since the last service, or unknown", "AWD fault light, or the rear never seems to engage", "You just bought the car"], "codes": [], "notes": ["Oil: G 055 175 A2 for the Mk5 R32's Gen 2 unit (rear diff prefix 0AV). Gen 4 cars (0BR) take G 060 175 A2. Haldex oil is specific; nothing else goes in.", "Filter: 02D 598 574 (kit with o-ring). Some kits list the old 02D 525 558 A; buy the kit for your generation.", "New fill is 0.85 L; a drain-and-fill takes about 0.65 L. One litre bottle covers it.", "The pump has a strainer screen you can pull and clean while the oil is out; owners who've had pump failures wish they had."], "confidence": {"level": "high", "n": 4, "note": "Part numbers, capacities and torques consistent across the Vortex R32 DIY, the TTRS DIY and vendor kits."}}, "parts": [{"tier": "oe", "name": "Haldex oil, 1 L", "pn": "G 055 175 A2", "note": "Gen 2 (0AV) units", "price": "$30–40", "links": []}, {"tier": "oe", "name": "Haldex filter kit", "pn": "02D 598 574", "note": "Filter + o-ring", "price": "$25–40", "links": []}, {"tier": "oe", "name": "Drain plug (8mm hex) and fill plug (5mm hex)", "pn": "N 910 827 01 · N 902 818 02", "note": "Replace if the hex is rounded", "price": "$6", "links": []}], "aftermarket": [{"name": "ECS / UroTuning Haldex service kits", "note": "Oil, filter and o-ring in one box; some add a magnetic drain plug.", "price": "$60–90", "signal": "One-box pick", "links": [{"store": "ECS R32 maintenance article", "url": "https://blog.ecstuning.com/top-mods-and-maintenance-for-your-vw-mk5-r32/"}]}], "tools": [{"name": "8mm and 5mm hex bits on a 3/8\" ratchet (clean the sockets out first)"}, {"name": "Fluid pump or a syringe with a hose; drain pan; T30 for the filter cover if fitted"}, {"name": "Torque wrench to 30 Nm; ramps or four stands so the car is level"}], "before": ["Car level. There's no dipstick; the level is the fill plug.", "Clean the plug hexes with a pick before you put a bit in them; a rounded hex here is a bad day.", "Warm oil drains better: a short drive first."], "steps": [{"n": 1, "title": "Find the unit", "blocks": [{"t": "text", "b": "Under the rear, the Haldex coupling is the cylindrical unit on the front of the rear differential where the propshaft arrives. Fill plug on the left side near the control module; drain plug on the bottom centre; filter on the right side behind a heat shield."}, {"t": "ill", "id": "haldex-hero", "cap": "Coupling in front, differential behind. Don't mix the oils."}]}, {"n": 2, "title": "Fill plug first, then drain", "blocks": [{"t": "text", "b": "Loosen the fill plug (5mm hex) first, so you know you can refill before you empty it. Then the drain plug (8mm hex) into a pan. Expect about 0.65 L. Look at it: dark and burnt means you were late."}]}, {"n": 3, "title": "Filter", "blocks": [{"t": "text", "b": "Right side of the unit: remove the filter cover, pull the old filter, new o-ring and filter, cover back. If the heat shield fights you, a stubby ratchet helps. While the oil is out, the pump's strainer screen can be pulled and cleaned; follow the kit or a video for its location on your unit."}]}, {"n": 4, "title": "Plug and fill", "blocks": [{"t": "text", "b": "Drain plug in with a new seal ring."}, {"t": "torque", "label": "Haldex drain plug (8mm hex)", "nm": 30, "c": {"level": "high", "n": 2, "note": "30 Nm (Vortex R32 DIY, TTRS DIY)."}}, {"t": "text", "b": "Pump oil in through the fill hole until it runs back out (about 0.65 L on a drain-and-fill). Fill plug in."}, {"t": "torque", "label": "Haldex fill plug (5mm hex)", "nm": 15, "c": {"level": "high", "n": 2, "note": "15 Nm (Vortex R32 DIY)."}}]}, {"n": 5, "title": "Drive, re-check", "blocks": [{"t": "text", "b": "Short drive, back on level ground, fill plug out: top up until it just spills, plug in. Some owners check with the oil at 20–40°C via VCDS; on the R32 the manual gives no temperature, so cold fill-to-spill plus a warm top-up is the practice."}]}], "alsoReplace": [{"name": "Rear differential and bevel box oil", "why": "Same afternoon, same plug sizes, and nobody else will remind you. See the 4Motion gear oil guide."}, {"name": "Haldex pump strainer", "why": "Oil is out; pull and clean it."}, {"name": "DSG service", "why": "Same 40k interval; do them together."}], "check": {"tab": "Read the oil", "title": "What came out?", "illId": "haldex-hero", "illCap": "Colour and smell.", "rows": [{"see": "Amber, thin, faint smell", "means": "On schedule.", "do": "Standard service."}, {"see": "Dark, burnt smell, flakes", "means": "Overdue; clutches have been hot.", "do": "Service, clean the strainer, service again at 10k."}, {"see": "AWD light after service", "means": "Air in the pump or a failing pump.", "do": "Drive a few cycles; if it persists, pump."}], "c": {"level": "community", "n": 3, "note": "Owner DIYs and vendor articles."}}, "aftercare": ["Level re-check after the first drive.", "Note the mileage; 40k or sooner."], "disagreements": [{"topic": "Interval", "pos": "40k oil and filter (ECS, factory) vs 20k oil / 40k filter (eEuroparts).", "call": "40k is the factory line; a 20k oil change is cheap on a car that gets driven hard."}, {"topic": "Level at temperature?", "pos": "The TTRS DIY checks at 20–40°C via VCDS; the R32 DIY says no temperature spec.", "call": "Cold fill-to-spill, warm top-up."}, {"topic": "Which oil", "pos": "G 055 vs G 060 in Audi capacity charts.", "call": "By rear-diff prefix: 0AV = G 055 175 A2."}], "sources": ["VWVortex 'Mini DIY: drain/fill bevel box, Haldex and rear differential' (R32)", "Audizine TTRS drivetrain fluids DIY (same Gen 2 hardware)", "eEuroparts R32 rear differential & Haldex DIY", "ECS 'Top Mods and Maintenance for your VW MK5 R32'", "UroTuning / VAG Garage kit listings (part numbers)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('awd-gear-oil',$j${"id": "awd-gear-oil", "title": "4Motion gear oil: rear differential & bevel box", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "haldex-hero", "alsoFits": "Mk5 R32; A3/TT 3.2 quattro (same units)", "category": "Drivetrain", "kind": "repair", "variants": {"question": "Which unit?", "hint": "Two gear-oil units besides the Haldex: the rear differential behind the coupling, and the bevel box (transfer case) on the side of the transmission that sends drive to the propshaft. Same oil, same plug sizes.", "options": [{"id": "rear", "label": "Rear differential", "when": "Behind the Haldex coupling, under the rear"}, {"id": "bevel", "label": "Bevel box (transfer case)", "when": "On the passenger side of the DSG, where the propshaft starts"}]}, "glance": {"timeFirst": "30 min each", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$30–40 per unit", "risk": "Rounded plug hexes · fill plug must open before the drain", "why": "VW calls these fluids lifetime. Owners who've opened them at 100k disagree. Each holds about a litre of gear oil, and the job is two plugs and a pump. Do them with the Haldex and you've done the whole 4Motion system in an afternoon.", "note": "Vortex R32 DIY and the TTRS DIY agree on oil, capacity and torque."}, "heroCap": "Rear differential sits behind the Haldex coupling; the bevel box hangs off the transmission up front. Both: drain plug low, fill plug on the side, fill till it spills.", "lifespan": {"title": "When to expect it", "headline": ["'Lifetime' per VW; owners do it every 40–60k with the Haldex"], "earliest": null, "detail": "No filter, no pump, just gear oil. Whine from the rear on the overrun is a differential bearing complaint, usually after years of dark oil.", "factors": ["Hard use", "Unknown history"], "inspect": ["None; keep the interval"], "confidence": {"level": "community", "n": 3, "note": "Owner practice; factory says lifetime."}}, "should": {"yesIf": ["Doing the Haldex anyway", "Unknown history", "Whine from the rear"], "codes": [], "notes": ["Oil: G 052 145 S2 (75W-90 spec) for both units. About 0.95 L each; a litre bottle per unit.", "Fill plug open first. Every time."], "confidence": {"level": "high", "n": 3, "note": "Consistent across both DIYs and ETKA per the Vortex thread."}}, "parts": [{"tier": "oe", "name": "Gear oil, 1 L per unit", "pn": "G 052 145 S2", "note": "", "price": "$25–35", "links": []}, {"tier": "oe", "name": "Drain and fill plugs", "pn": "N 910 827 01 · N 902 818 02", "note": "Same as the Haldex; replace if rounded", "price": "$6", "links": []}], "aftermarket": [{"name": "Ravenol / Motul 75W-90 meeting the G 052 145 spec", "note": "Fine substitutes; check the spec on the bottle.", "price": "$20–30", "signal": "Meets spec", "links": []}], "tools": [{"name": "8mm and 5mm hex bits, 3/8\" ratchet; fluid pump; pan"}, {"name": "Torque wrench to 30 Nm; level ground"}], "before": ["Car level.", "Clean the plug hexes first.", "Fill plug loosened before the drain comes out."], "steps": [{"n": 1, "title": "Find the plugs", "blocks": [{"t": "text", "b": "Rear differential: behind the Haldex coupling. Fill plug on the side (left), drain on the bottom. Both hex plugs, same sizes as the Haldex.", "only": ["rear"]}, {"t": "text", "b": "Bevel box: on the passenger side of the transmission, where the propshaft leaves. Fill plug on its side, drain on the bottom. Access from below with the belly pan off.", "only": ["bevel"]}, {"t": "ill", "id": "haldex-hero", "cap": "Rear diff behind the coupling; bevel box up front on the transmission."}]}, {"n": 2, "title": "Fill plug, then drain", "blocks": [{"t": "text", "b": "Loosen the fill plug (5mm hex). Drain plug (8mm hex) into a pan; about a litre. Look for metal glitter on the magnet or in the oil."}]}, {"n": 3, "title": "Refill to spill", "blocks": [{"t": "text", "b": "Drain plug in with a new seal."}, {"t": "torque", "label": "Drain plug (8mm hex)", "nm": 30, "c": {"level": "high", "n": 2, "note": "30 Nm (both DIYs)."}}, {"t": "text", "b": "Pump G 052 145 S2 in until it runs back out of the fill hole. No temperature spec on these units. Fill plug in."}, {"t": "torque", "label": "Fill plug (5mm hex)", "nm": 15, "c": {"level": "high", "n": 2, "note": "15 Nm."}}]}, {"n": 4, "title": "The other unit, belly pan on", "blocks": [{"t": "text", "b": "Repeat on the other unit if you're doing both. Belly pan, drive, check for drips."}]}], "alsoReplace": [{"name": "Haldex service", "why": "Same afternoon; see its guide."}, {"name": "Propshaft centre support bearing", "why": "You're looking at the propshaft. A cracked rubber support is a known Mk5 4Motion vibration source."}], "check": {"tab": "Read the oil", "title": "What came out?", "illId": "haldex-hero", "illCap": "Glitter is bad.", "rows": [{"see": "Amber to brown, clean magnet", "means": "Fine.", "do": "Refill."}, {"see": "Black, metallic sheen", "means": "Long overdue; bearings working hard.", "do": "Refill; listen for whine; plan a second change soon."}, {"see": "Chunks", "means": "Something's breaking.", "do": "Specialist."}], "c": {"level": "community", "n": 3, "note": "Owner practice."}}, "aftercare": ["Drip check after a day."], "disagreements": [{"topic": "Lifetime fluid?", "pos": "VW: yes. Owners: no.", "call": "Change it with the Haldex."}], "sources": ["VWVortex 'Mini DIY' (R32 0AV)", "Audizine TTRS drivetrain fluids DIY", "eEuroparts R32 rear differential article"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('coolant-pipe-r32',$j${"id": "coolant-pipe-r32", "title": "Coolant pipe & thermostat housing (VR6)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "haldex-hero", "alsoFits": "Mk5 R32 (3.2 VR6 BUB)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "3–4 hr", "timeRepeat": "—", "difficulty": 3, "cost": "—", "risk": "—", "why": "The VR6's plastic thermostat housing and the main coolant pipe behind the engine (the 'crack pipe') split with age and leak. Coolant smell and a low level with pink crust at the back of the block are the signs. Both are replaced together, with the thermostat, and aluminium replacements exist.", "note": "Common past 80,000 miles. Difficulty 3: coolant drain, access behind the engine."}, "heroCap": "Placeholder illustration.", "lifespan": {"title": "When to expect it", "headline": ["Common past 80,000 miles. Difficulty 3: coolant drain, access behind the engine."], "earliest": null, "detail": "The VR6's plastic thermostat housing and the main coolant pipe behind the engine (the 'crack pipe') split with age and leak. Coolant smell and a low level with pink crust at the back of the block are the signs. Both are replaced together, with the thermostat, and aluminium replacements exist.", "factors": [], "inspect": [], "confidence": {"level": "community", "n": 2, "note": "Stub; sourcing pending"}}, "should": {"yesIf": [], "codes": [], "notes": ["This guide is a placeholder so the job is on the map for R32 owners; the full procedure and torque values are being sourced."], "confidence": {"level": "community", "n": 1, "note": "Stub"}}, "parts": [], "aftermarket": [], "tools": [], "before": [], "steps": [{"n": 1, "title": "Coming soon", "blocks": [{"t": "text", "b": "Full procedure pending. The summary above is accurate; use it to decide urgency."}]}], "alsoReplace": [], "check": {"tab": "Notes", "title": "What we know so far", "illId": "haldex-hero", "illCap": "", "rows": [], "c": {"level": "community", "n": 1, "note": "Stub"}}, "aftercare": [], "disagreements": [], "sources": ["R32 owner forums; ECS R32 article"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('timing-chain-r32',$j${"id": "timing-chain-r32", "title": "Timing chain guides & tensioner (VR6)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "haldex-hero", "alsoFits": "Mk5 R32 (3.2 VR6 BUB)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "2–3 days", "timeRepeat": "—", "difficulty": 5, "cost": "—", "risk": "—", "why": "The VR6's chains live at the back of the engine against the firewall; the plastic upper guides wear and the tensioner loses grip past 100k. A rattle at idle from the transmission side is the warning. It's a transmission-out job on a 4Motion DSG car, and the biggest one in the R32 catalog.", "note": "Past 100,000 miles is when owners start listening. Difficulty 5: engine and transmission separated."}, "heroCap": "Placeholder illustration.", "lifespan": {"title": "When to expect it", "headline": ["Past 100,000 miles is when owners start listening. Difficulty 5: engine and transmission separated."], "earliest": null, "detail": "The VR6's chains live at the back of the engine against the firewall; the plastic upper guides wear and the tensioner loses grip past 100k. A rattle at idle from the transmission side is the warning. It's a transmission-out job on a 4Motion DSG car, and the biggest one in the R32 catalog.", "factors": [], "inspect": [], "confidence": {"level": "community", "n": 2, "note": "Stub; sourcing pending"}}, "should": {"yesIf": [], "codes": [], "notes": ["This guide is a placeholder so the job is on the map for R32 owners; the full procedure and torque values are being sourced."], "confidence": {"level": "community", "n": 1, "note": "Stub"}}, "parts": [], "aftermarket": [], "tools": [], "before": [], "steps": [{"n": 1, "title": "Coming soon", "blocks": [{"t": "text", "b": "Full procedure pending. The summary above is accurate; use it to decide urgency."}]}], "alsoReplace": [], "check": {"tab": "Notes", "title": "What we know so far", "illId": "haldex-hero", "illCap": "", "rows": [], "c": {"level": "community", "n": 1, "note": "Stub"}}, "aftercare": [], "disagreements": [], "sources": ["R32 owner forums; ECS R32 article"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('pcv-r32',$j${"id": "pcv-r32", "title": "Crankcase breather / PCV (VR6)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "haldex-hero", "alsoFits": "Mk5 R32 (3.2 VR6 BUB)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "—", "difficulty": 2, "cost": "—", "risk": "—", "why": "The VR6's crankcase ventilation is built into the valve cover, with a breather hose to the intake. A failed diaphragm means rough idle, oil consumption and a whistle. The fix on this engine is often the whole valve cover.", "note": "Age-related; check when oil consumption rises. Difficulty 2."}, "heroCap": "Placeholder illustration.", "lifespan": {"title": "When to expect it", "headline": ["Age-related; check when oil consumption rises. Difficulty 2."], "earliest": null, "detail": "The VR6's crankcase ventilation is built into the valve cover, with a breather hose to the intake. A failed diaphragm means rough idle, oil consumption and a whistle. The fix on this engine is often the whole valve cover.", "factors": [], "inspect": [], "confidence": {"level": "community", "n": 2, "note": "Stub; sourcing pending"}}, "should": {"yesIf": [], "codes": [], "notes": ["This guide is a placeholder so the job is on the map for R32 owners; the full procedure and torque values are being sourced."], "confidence": {"level": "community", "n": 1, "note": "Stub"}}, "parts": [], "aftermarket": [], "tools": [], "before": [], "steps": [{"n": 1, "title": "Coming soon", "blocks": [{"t": "text", "b": "Full procedure pending. The summary above is accurate; use it to decide urgency."}]}], "alsoReplace": [], "check": {"tab": "Notes", "title": "What we know so far", "illId": "haldex-hero", "illCap": "", "rows": [], "c": {"level": "community", "n": 1, "note": "Stub"}}, "aftercare": [], "disagreements": [], "sources": ["R32 owner forums; ECS R32 article"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('intake-r32',$j${"id": "intake-r32", "title": "Aftermarket intake (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "haldex-hero", "alsoFits": "Mk5 R32 (3.2 VR6 BUB)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "1 hr", "timeRepeat": "—", "difficulty": 2, "cost": "—", "risk": "—", "why": "R32 intakes (Neuspeed, Carbonio, VF, BSH) replace the airbox and pipe to the VR6's throttle body. Sound is the main gain on a naturally aspirated six; brand instructions vary.", "note": "Owners do it early for the induction howl. Difficulty 2."}, "heroCap": "Placeholder illustration.", "lifespan": {"title": "When to expect it", "headline": ["Owners do it early for the induction howl. Difficulty 2."], "earliest": null, "detail": "R32 intakes (Neuspeed, Carbonio, VF, BSH) replace the airbox and pipe to the VR6's throttle body. Sound is the main gain on a naturally aspirated six; brand instructions vary.", "factors": [], "inspect": [], "confidence": {"level": "community", "n": 2, "note": "Stub; sourcing pending"}}, "should": {"yesIf": [], "codes": [], "notes": ["This guide is a placeholder so the job is on the map for R32 owners; the full procedure and torque values are being sourced."], "confidence": {"level": "community", "n": 1, "note": "Stub"}}, "parts": [], "aftermarket": [], "tools": [], "before": [], "steps": [{"n": 1, "title": "Coming soon", "blocks": [{"t": "text", "b": "Full procedure pending. The summary above is accurate; use it to decide urgency."}]}], "alsoReplace": [], "check": {"tab": "Notes", "title": "What we know so far", "illId": "haldex-hero", "illCap": "", "rows": [], "c": {"level": "community", "n": 1, "note": "Stub"}}, "aftercare": [], "disagreements": [], "sources": ["R32 owner forums; ECS R32 article"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('exhaust-r32',$j${"id": "exhaust-r32", "title": "Downpipe, headers & cat-back (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "haldex-hero", "alsoFits": "Mk5 R32 (3.2 VR6 BUB)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "2–4 hr", "timeRepeat": "—", "difficulty": 3, "cost": "—", "risk": "—", "why": "The R32's exhaust is its own system: a single downpipe from the VR6 manifolds, a resonated mid-section and the centre-exit twin-tip rear. Milltek, HPA and Eurojet make cat-backs; headers and high-flow downpipes exist for the sound and a few horsepower.", "note": "Cat-back is the classic R32 mod. Difficulty 2–3."}, "heroCap": "Placeholder illustration.", "lifespan": {"title": "When to expect it", "headline": ["Cat-back is the classic R32 mod. Difficulty 2–3."], "earliest": null, "detail": "The R32's exhaust is its own system: a single downpipe from the VR6 manifolds, a resonated mid-section and the centre-exit twin-tip rear. Milltek, HPA and Eurojet make cat-backs; headers and high-flow downpipes exist for the sound and a few horsepower.", "factors": [], "inspect": [], "confidence": {"level": "community", "n": 2, "note": "Stub; sourcing pending"}}, "should": {"yesIf": [], "codes": [], "notes": ["This guide is a placeholder so the job is on the map for R32 owners; the full procedure and torque values are being sourced."], "confidence": {"level": "community", "n": 1, "note": "Stub"}}, "parts": [], "aftermarket": [], "tools": [], "before": [], "steps": [{"n": 1, "title": "Coming soon", "blocks": [{"t": "text", "b": "Full procedure pending. The summary above is accurate; use it to decide urgency."}]}], "alsoReplace": [], "check": {"tab": "Notes", "title": "What we know so far", "illId": "haldex-hero", "illCap": "", "rows": [], "c": {"level": "community", "n": 1, "note": "Stub"}}, "aftercare": [], "disagreements": [], "sources": ["R32 owner forums; ECS R32 article"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('battery',$j${"id": "battery", "title": "Battery replacement", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI · 3.2 R32", "heroId": "battery-hero", "alsoFits": "All Mk5 platform cars (Golf, GTI, Jetta, Eos, A3); no battery coding on this generation", "category": "Electrical", "kind": "repair", "glance": {"timeFirst": "30 min", "timeRepeat": "15 min", "difficulty": 1, "cost": "$150–350", "risk": "Negative off first, on last · battery is heavy · acid", "why": "A weak battery on a modern VW does strange things before it dies: random warning lights, a DSG that acts up, a radio that resets. Five years is a fair life; if yours is older or the car has been slow to crank on a cold morning, this is a half-hour job with one rule that matters.", "note": "No coding is needed on a Mk5, which is the whole reason this is easy. Later cars differ."}, "heroCap": "Battery under a plastic cover on the driver's side. Negative terminal off first, hold-down clamp at the base, lift it out. Group H6 (also called 48 or L3).", "lifespan": {"title": "When to expect it", "headline": ["Typically 4–6 years; sooner in hot climates"], "earliest": "3 years in the desert Southwest", "detail": "Slow cranking on a cold start, a dash that flickers on crank, or a jump start you needed once are the warnings. Any parts store will load-test it for free; below about 12.4 V resting, or a failed load test, replace it before it strands you or corrupts a module with low voltage.", "factors": ["Heat", "Short trips (never fully charged)", "Parasitic drain from an aftermarket stereo or alarm", "Sitting for weeks"], "inspect": ["Resting voltage once a season: 12.6 V is healthy, 12.4 is tired, 12.2 is done"], "confidence": {"level": "community", "n": 3, "note": "General practice; consistent."}}, "should": {"yesIf": ["Slow crank, especially cold", "Failed a load test or reads under 12.4 V rested", "Date sticker says 5+ years", "Odd electrical gremlins that come and go"], "codes": [], "notes": ["Size: Group H6 (DIN L3 / BCI 48). The Mk5 GTI's tray and hold-down are made for it. Optima's H6 is the DH6; Odyssey's is the 48-720.", "AGM or flooded: both work on a Mk5 because it has no battery management module that needs to be told. AGM tolerates heat and vibration better and costs more. Either is fine; AGM is the upgrade.", "Radio codes: most Mk5 head units don't ask for one, but check your manual or glovebox card before you disconnect. A cheap memory saver plugged into the OBD port avoids the question entirely."], "confidence": {"level": "high", "n": 3, "note": "Fitment and the no-coding point are consistent across sources; AGM guidance is standard practice."}}, "parts": [{"tier": "oe", "name": "Battery, Group H6 (L3/48), flooded or AGM", "pn": "e.g. Varta, Bosch, Interstate H6", "note": "12V, ~70 Ah, 700+ CCA", "price": "$150–250", "links": []}, {"tier": "oe", "name": "Terminal protector spray or grease, felt washers", "pn": "—", "note": "", "price": "$8", "links": []}], "aftermarket": [{"name": "Optima RedTop DH6", "note": "AGM, spiral cell, high cranking amps, very vibration resistant. The forum's default upgrade.", "price": "$280–350", "signal": "Forum favorite", "links": []}, {"name": "Optima YellowTop DH6", "note": "Deep-cycle AGM for cars with big stereos or lots of accessories; same case.", "price": "$300–360", "signal": "For accessory-heavy cars", "links": []}, {"name": "Odyssey 48-720 (Extreme)", "note": "AGM with a long warranty and excellent heat tolerance. Slightly taller; check the cover clears.", "price": "$300–380", "signal": "Longevity pick", "links": []}, {"name": "Varta / Bosch AGM H6", "note": "OE-supplier AGM at a friendlier price. Same battery as many factory fits.", "price": "$200–260", "signal": "Value AGM", "links": []}], "tools": [{"name": "10mm wrench (terminals), 13mm socket with extension (hold-down)"}, {"name": "Terminal brush, gloves, safety glasses"}, {"name": "Optional: OBD memory saver; multimeter"}], "before": ["Engine off, key out of the ignition, windows closed (you'll relearn one-touch afterwards).", "Note your radio code if your head unit has one.", "Negative terminal comes off first and goes on last. Every time."], "steps": [{"n": 1, "title": "Cover off", "blocks": [{"t": "text", "b": "Push the release tab on the battery cover, pivot it up and unhook it at the rear."}]}, {"n": 2, "title": "Negative, then positive", "caution": true, "blocks": [{"t": "text", "b": "10mm: loosen the negative (black, marked −) clamp nut, twist the clamp off the post and tuck the cable where it can't touch the terminal. Then the positive (red, under its flip cover)."}, {"t": "warn", "b": "Negative first. If the wrench touches the body while you're on the positive terminal with the negative still connected, you've made a welder. Glasses on; batteries vent hydrogen."}, {"t": "ill", "id": "battery-hero", "cap": "Order: negative off, positive off, clamp, lift. Reverse to install."}]}, {"n": 3, "title": "Hold-down and lift", "blocks": [{"t": "text", "b": "13mm on an extension: the hold-down clamp bolt at the base of the battery, on the inboard side. Remove the clamp. If the front half of the battery box is in the way, lift it off. Lift the battery straight up and out; it's about 45 lb and awkward. Keep it level."}]}, {"n": 4, "title": "Clean and drop in", "blocks": [{"t": "text", "b": "Brush the terminal clamps clean inside. Check the tray for acid crust and wipe it. New battery in, same orientation (positive toward the front, matching the cables), seated in the tray's lip. Hold-down clamp back on and snug: it should not rock, but you're clamping plastic, so don't crank it."}]}, {"n": 5, "title": "Positive, then negative", "blocks": [{"t": "text", "b": "Positive clamp on its post first, nut snug (10mm; snug, the clamps distort if over-tightened). Then the negative. A wipe of terminal protector on both. Box half and cover back on."}]}, {"n": 6, "title": "Relearn the little things", "blocks": [{"t": "text", "b": "Start it. Set the clock. One-touch windows: close each window fully and hold the switch up for a second more, then open fully and hold down a second; repeat for each. Turn the steering wheel lock to lock once so the steering-angle sensor recentres (clears the ESP light if it's on). Sunroof: hold close until it cycles. That's it; no coding on this car."}]}], "alsoReplace": [{"name": "Ground strap and terminal clamps", "why": "Green or crusty clamps cause the same symptoms as a bad battery. A new clamp is $10."}, {"name": "Check the alternator", "why": "With the new battery in and the engine running, you should see 13.8–14.4 V at the terminals. If not, the battery wasn't the problem."}], "check": {"tab": "Test first", "title": "Is it the battery?", "illId": "battery-hero", "illCap": "A multimeter answers most of this.", "rows": [{"see": "Rested voltage 12.6+, cranks fine", "means": "Battery is fine.", "do": "Look elsewhere for your symptom."}, {"see": "Rested 12.2–12.4, slow crank", "means": "Tired.", "do": "Load test; probably replace."}, {"see": "13.8–14.4 V running", "means": "Alternator is fine.", "do": "Battery only."}, {"see": "Under 13.5 V running, or over 15", "means": "Charging problem.", "do": "Alternator or regulator; a new battery will just die again."}], "c": {"level": "high", "n": 3, "note": "Standard electrical diagnosis."}}, "aftercare": ["Write the install date on the battery with a marker.", "Recycle the old one; the store credits the core."], "disagreements": [{"topic": "Does it need coding?", "pos": "Newer VWs do; people assume all do.", "call": "Not the Mk5. Plug and play."}, {"topic": "AGM or flooded?", "pos": "Forum arguments about cost.", "call": "Both work here; AGM is the nicer part if the budget allows."}], "sources": ["ECS 02Q transmission guide (battery removal steps and fastener sizes)", "Optima / Odyssey fitment listings", "Forum consensus on Mk5 relearn procedures and the absence of battery coding"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('headlights',$j${"id": "headlights", "title": "Headlight bulbs & housings", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI · 3.2 R32", "heroId": "headlight-hero", "alsoFits": "2006–09 GTI (halogen and bi-xenon); Golf/Rabbit and Jetta share the technique, not the housings", "category": "Electrical", "kind": "repair", "variants": {"question": "Which headlights does your car have?", "hint": "US Mk5 GTIs came both ways. Bi-xenon housings have a projector with a bluish-white beam and a small inner halogen; halogen housings use two ordinary reflector bulbs.", "options": [{"id": "halogen", "label": "Halogen", "when": "H7 bulbs, yellow-white light, cheap to replace"}, {"id": "xenon", "label": "Bi-xenon (HID)", "when": "One D2S bulb does low and high via a shutter; ~$50 each"}]}, "glance": {"timeFirst": "1–1.5 hr (assembly out) · 20 min if you can reach in", "timeRepeat": "30 min", "difficulty": 2, "cost": "$20–40 halogen · $80–120 xenon pair · $300+ per housing", "risk": "HID ballast voltage · scratching the bumper · touching halogen glass", "why": "Bulbs dim before they die, and one dead low beam is a ticket. On this car the honest way to change either bulb type is to take the headlight out, which means loosening the bumper cover. It sounds worse than it is, and while it's out you can fix the fogged lens or swap the whole housing.", "note": "Pelican and the forums agree: possible in place with small hands on the passenger side, painful on the driver's side, easy with the assembly out."}, "heroCap": "Headlight held by screws that hide behind the bumper cover's top edge. Loosen the cover, unscrew the housing, pull it forward, and every bulb cap is in front of you.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Halogen H7 low beams: typically 1–3 years of nightly use", "only": ["halogen"]}, {"text": "D2S xenon bulbs: typically 5–8 years; they dim and shift colour rather than fail suddenly", "only": ["xenon"]}], "earliest": "Cheap 'blue' halogens can go in months", "detail": "Halogens burn out; xenons fade toward purple and lose output long before they quit. Replace xenons in pairs so the colours match, and because the second one is close behind. Housings themselves go hazy from UV on the outside (polish) or from a failed seal on the inside (replace).", "factors": ["Daytime running lights on all the time", "Vibration from a rough road", "Touching halogen glass on install"], "inspect": ["Look at your low beams on a garage wall once a year: colour match and pattern"], "confidence": {"level": "community", "n": 3, "note": "Owner experience; no factory interval."}}, "should": {"yesIf": ["Low beam out, or the dash says 'dipped beam'", "Beams noticeably different colours (xenon)", "Lens fogged inside or badly hazed", "You want to upgrade housings"], "codes": [], "notes": [{"text": "H7 for the low beam. Most Mk5 GTI halogen housings also use H7 for the high beam, but confirm by reading the old bulb's base before you buy. Any decent brand (Osram, Philips) beats a blue-tinted 'upgrade' bulb, which is dimmer and short-lived.", "only": ["halogen"]}, {"text": "The outer projector's single D2S bulb does both low and high beam; a shutter moves for high. The small inner lamp is an H7 'flash to pass' that some owners code to act as an extra high beam. When the dash complains about the low beam, it's the D2S. Buy a name brand (Philips, Osram) and replace both sides.", "only": ["xenon"]}, {"text": "The ballast makes several thousand volts to light a D2S. Battery disconnected, lights off, and never operate a ballast with the bulb out.", "only": ["xenon"]}, "LED 'H7 replacement' bulbs in halogen reflector housings scatter light and blind other drivers; most aren't legal for road use. A better halogen is the honest upgrade for a reflector; a housing swap to bi-xenon is the real one."], "confidence": {"level": "medium", "n": 3, "note": "Pelican article and forum threads; bulb-type detail confirmed for xenon, halogen high beam noted as 'confirm on the old bulb'."}}, "parts": [{"tier": "oe", "name": "H7 halogen bulbs (pair)", "pn": "Osram Night Breaker / Philips X-tremeVision", "note": "Replace in pairs", "price": "$20–40", "links": [], "only": ["halogen"]}, {"tier": "oe", "name": "D2S xenon bulbs (pair)", "pn": "Philips 85122 / Osram 66240", "note": "Replace in pairs; name brand only", "price": "$80–120", "links": [], "only": ["xenon"]}, {"tier": "oe", "name": "Headlight housing (each), if replacing", "pn": "halogen or bi-xenon by VIN", "note": "OE (Hella) or OE-supplier; aftermarket varies widely", "price": "$300–900", "links": []}, {"tier": "oe", "name": "Bumper cover clips/screws", "pn": "a few break every time", "note": "", "price": "$10", "links": []}], "aftermarket": [{"name": "OEM-style bi-xenon housings (Hella)", "note": "The real upgrade for a halogen car: projector beam, proper cutoff, and legal. Needs the xenon wiring/ballasts or a harness, plus the auto-levelling if you want it correct.", "price": "$700–1,200 / pair", "signal": "The proper upgrade", "links": []}, {"name": "Depo / TYC replacement housings", "note": "Budget replacements for a fogged or cracked lens. Fit varies; beam quality is fine for halogen, hit-and-miss for projectors.", "price": "$150–300 each", "signal": "Budget lens fix", "links": []}, {"name": "Osram Night Breaker / Philips X-treme H7", "note": "Brighter, whiter halogens that are still legal. Shorter life than standard.", "price": "$25–40 / pair", "signal": "Best legal halogen", "links": [], "only": ["halogen"]}], "tools": [{"name": "T25 and T30 Torx, 10mm socket, trim tool for bumper clips"}, {"name": "Nitrile gloves (halogen glass), a soft blanket to set the housing on"}, {"name": "Flashlight; a friend to hold the bumper corner"}], "before": ["Battery negative disconnected, especially for xenon.", "Don't touch halogen glass with bare fingers; the oil creates a hot spot and the bulb fails early. If you did, wipe it with alcohol.", "Lay a blanket on the fender edge; you'll rest the housing there."], "steps": [{"n": 1, "title": "Try the shortcut (passenger side, halogen)", "only": ["halogen"], "blocks": [{"t": "text", "b": "With the airbox snorkel out of the way, small hands can reach the low-beam cap on the passenger side from above: twist the round cap off, unplug the bulb, release its wire clip, swap it. If you can do both sides this way, you're done in twenty minutes. Most people can't reach the driver's side past the fuse box and battery; for that side, continue."}]}, {"n": 2, "title": "Loosen the bumper cover's top edge", "blocks": [{"t": "text", "b": "Behind the grille and along the top of the bumper cover: Torx screws into the radiator support (T25/T30) and clips. Remove the screws along the top and the ones in the wheel-arch liner at the bumper corner (T25) so the corner of the cover can be pulled forward a few inches. Pelican's advice is to just remove the cover entirely; it's another fifteen minutes and saves scratching it."}, {"t": "ill", "id": "headlight-hero", "cap": "The housing screws are behind the bumper cover's edge. Loosen the cover, and they're right there."}]}, {"n": 3, "title": "Headlight out", "blocks": [{"t": "text", "b": "With the cover pulled forward, the headlight mounting screws are visible (top edge and outer side). Remove them, unplug the main connector on the back of the housing, and slide the housing forward and out. Set it face-down on the blanket."}, {"t": "warn", "b": "Xenon: the ballast is on the housing. Don't unplug or plug anything with the lights on, and don't power a ballast without a bulb.", "only": ["xenon"]}]}, {"n": 4, "title": "Swap the bulbs", "blocks": [{"t": "text", "b": "Round caps on the back: twist off. Low beam H7: unplug, squeeze the wire retainer clip, lift the bulb out, new one in with the tab orientation matching, clip, plug, cap. High beam: same. Gloves on the glass.", "only": ["halogen"]}, {"t": "text", "b": "Remove the projector's rear cap, unplug the igniter connector from the D2S, release the bulb's retaining ring or clip, lift the bulb straight out without touching the glass, seat the new one in the same orientation, retainer, igniter, cap. Do the other side too; colours must match.", "only": ["xenon"]}, {"t": "text", "b": "While it's out: if the lens is hazy outside, polish it now with a headlight restoration kit; it's a hundred times easier on the bench. Moisture inside means a failed seal, and that's a housing, not a bulb."}]}, {"n": 5, "title": "Housing back in, cover back on", "blocks": [{"t": "text", "b": "Plug the housing in, slide it into its locating pins, screws in. Bumper cover corner back, screws and clips. Battery negative reconnected."}]}, {"n": 6, "title": "Aim check", "blocks": [{"t": "text", "b": "Park 25 feet from a wall on level ground. Low-beam cutoffs should be level with each other and just below headlight height. Adjusters are on the back of the housing (T-handle or hex). Xenon cars with auto-levelling: turn the car on and watch the beams settle; if one stays low, the level sensor arm on the control arm is disconnected."}]}], "alsoReplace": [{"name": "Turn signal and DRL bulbs", "why": "Same housing, same trip. The amber bulbs fade and the sockets corrode."}, {"name": "Lens restoration", "why": "Housing on a bench is when to polish and UV-coat it."}, {"name": "Headlight washer nozzle / level sensor check", "why": "Xenon cars: while the bumper corner is loose, check the washer hose and that the level sensor arm is attached.", "only": ["xenon"]}], "check": {"tab": "Bulb or housing?", "title": "Bulb, housing, or something else?", "illId": "headlight-hero", "illCap": "Colour, moisture and the dash message narrow it quickly.", "rows": [{"see": "One low beam out, dash message", "means": "Bulb (D2S on xenon, H7 on halogen).", "do": "Replace, in pairs."}, {"see": "Beam flickers or takes several tries to light (xenon)", "means": "Bulb at end of life, or the ballast/igniter.", "do": "New bulbs first; if it persists, ballast."}, {"see": "Fog inside the lens", "means": "Seal failed.", "do": "Housing, or a careful reseal."}, {"see": "Both dim, yellow lens", "means": "UV haze on the polycarbonate.", "do": "Polish and coat."}], "c": {"level": "community", "n": 3, "note": "Owner threads and vendor guidance."}}, "aftercare": ["Check aim after a week.", "Xenon colour mismatch that persists: the ballasts differ or one bulb is a different brand."], "disagreements": [{"topic": "Can you do it in place?", "pos": "Some owners manage the passenger side; Pelican says take the assembly out.", "call": "Try the shortcut on the passenger side; take it out for the driver's side and for any xenon."}, {"topic": "Halogen high-beam bulb type", "pos": "H7 on most; not confirmed from a factory table.", "call": "Read the old bulb."}, {"topic": "LED drop-ins", "pos": "Popular; cheap.", "call": "Not in a reflector housing. Glare, and not legal on the road."}], "sources": ["Pelican Parts Mk5 GTI headlight bulb and assembly article", "VWVortex 'GTI Headlight Bulb Replacement' (bi-xenon detail)", "Owner threads on in-place bulb access", "Bulb and housing listings"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('brake-flush',$j${"id": "brake-flush", "title": "Brake fluid flush", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI · 3.2 R32", "heroId": "bleed-order", "alsoFits": "All Mk5 platform cars (Golf, Jetta, A3, Eos): same order", "category": "Brakes", "kind": "repair", "variants": {"question": "Manual or DSG?", "hint": "Manual cars share the brake reservoir with the clutch slave cylinder, which gets bled first.", "options": [{"id": "manual", "label": "6-speed manual", "when": "Clutch slave bled first"}, {"id": "dsg", "label": "DSG", "when": "Brakes only"}]}, "glance": {"timeFirst": "1 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$25–40 (fluid) + a $50 pressure bleeder once", "risk": "Fluid eats paint · don't let the reservoir run dry", "why": "Brake fluid absorbs water from the air through the hoses. Wet fluid boils at a lower temperature (soft pedal after hard stops) and corrodes the ABS unit and calipers from the inside. VW says change it every two years; almost nobody does.", "note": "An hour with a pressure bleeder. Double that with a helper on the pedal."}, "heroCap": "VW's order is front-left, front-right, rear-left, rear-right, because of how the ABS unit is plumbed. Clutch slave first on a manual.", "lifespan": {"title": "When to expect it", "headline": ["Factory: first change at 3 years, then every 2 years, regardless of miles"], "earliest": null, "detail": "Time, not distance. Fluid that's dark amber or brown in the reservoir is overdue. A cheap test strip or moisture tester tells you the water content; above 3% is time.", "factors": ["Humid climate", "Track days (boil it once and it's done)", "Unknown history"], "inspect": ["Look at the reservoir colour at every oil change"], "confidence": {"level": "medium", "n": 3, "note": "Factory schedule via a vendor summary; owner practice agrees."}}, "should": {"yesIf": ["Over two years since the last flush, or unknown", "Fluid is dark", "Pedal goes soft after repeated hard stops", "You just did calipers, lines, or a clutch"], "codes": [], "notes": ["DOT 4 only, from a sealed bottle. An opened bottle on the shelf has been absorbing water for months. Buy small bottles.", "If the reservoir runs dry during the job, air enters the ABS unit and a scan tool (VCDS) is needed to cycle it out. Keep it topped.", "R32: DSG only, so choose DSG above. Same bleed order."], "confidence": {"level": "high", "n": 4, "note": "Method and rationale consistent across the manual, two owner write-ups and vendor guidance."}}, "parts": [{"tier": "oe", "name": "DOT 4 brake fluid, 1.5 L", "pn": "VW 501 14 spec (ATE TYP200, Pentosin, Motul DOT 4)", "note": "Sealed bottles", "price": "$25–40", "links": []}, {"tier": "oe", "name": "Bleeder nipple dust caps", "pn": "if missing", "note": "", "price": "$4", "links": []}], "aftermarket": [{"name": "ATE TYP200 / Motul RBF600", "note": "Higher dry and wet boiling points for track use. RBF600 needs more frequent changes; TYP200 is the sensible middle.", "price": "$20–35 / L", "signal": "Track-day pick", "links": []}], "tools": [{"name": "Pressure bleeder (Motive or similar) with the VW/Audi 45mm cap", "note": "Turns a two-person job into one"}, {"name": "11mm wrench (flare nut or ratcheting), clear hose, catch bottle"}, {"name": "Turkey baster, rags, spray bottle of water for drips"}], "before": ["Cover the paint around the reservoir and behind each wheel.", "Pump the bleeder to 10–15 psi, not 30; higher isn't needed and stresses the master-cylinder seals.", "Wheels off makes the rear nipples much easier, but it can be done through the spokes."], "steps": [{"n": 1, "title": "Wheels off (recommended)", "blocks": [{"t": "text", "b": "Raise the car on four stands, wheels off, or do it one axle at a time. Find the bleeder nipple on each caliper (top, inboard) and pop the dust cap."}]}, {"n": 90, "title": "Set up the pressure bleeder", "blocks": [{"t": "text", "b": "Turkey-baster the old fluid out of the reservoir down to the minimum line and refill with fresh DOT 4 from a sealed bottle. Screw the bleeder cap onto the reservoir and pump it to 10–15 psi. Keep the reservoir topped the whole time; if it runs dry the ABS unit takes in air and only a scan tool can bleed it."}, {"t": "warn", "b": "Brake fluid strips paint in minutes. Cover the fender and wing, keep a spray bottle of water handy, and wipe drips immediately."}]}, {"n": 91, "title": "Bleed in the manual's order", "caution": true, "blocks": [{"t": "text", "b": "Manual car first: 11mm on the clutch slave bleeder (on the bell housing), let 50 ml run, close, pump the clutch pedal 10–15 times, open again for another 50 ml, close.", "only": ["manual"]}, {"t": "text", "b": "The brakes: front-left, front-right, rear-left, rear-right. Yes, front first; the ABS unit's layout makes the usual furthest-first rule wrong on this car. At each caliper: dust cap off, 11mm wrench on the nipple, hose into a catch bottle, open until the fluid runs clear and bubble-free, close, cap."}, {"t": "ill", "id": "bleed-order", "cap": "The order VW specifies. Clutch slave first on a manual."}, {"t": "note", "b": "Finishing touch owners swear by: after the pressure bleed, have a helper do five firm pedal strokes per caliper (open the nipple with the pedal down, close before it comes up) to chase any last air."}]}, {"n": 92, "title": "Close up and test", "blocks": [{"t": "text", "b": "Release bleeder pressure, remove the cap, set the reservoir level between the marks (not above MAX; the pads will wear and the level will rise as they're changed). Pedal should be firm within the first inch. Drive gently around the block, brake progressively harder, and check every bleeder for weeping."}]}], "alsoReplace": [{"name": "Clutch slave bleed", "why": "On a manual it shares the reservoir; it's already first in the order.", "only": ["manual"]}, {"name": "Rear brake hose check", "why": "Look for cracks or bulges in the rubber hoses while you're at each corner. See the stainless-line guide if they're tired."}], "check": {"tab": "Read the fluid", "title": "What came out?", "illId": "bleed-order", "illCap": "Colour tells the story.", "rows": [{"see": "Pale yellow, clear", "means": "Recent. Someone loved this car.", "do": "Note the date; next in two years."}, {"see": "Amber to brown", "means": "Years old, wet.", "do": "Flush until clear at every corner. Expect more than a litre."}, {"see": "Black flecks or sludge", "means": "Seals breaking down or a caliper cooking the fluid.", "do": "Flush, then inspect that caliper for drag; rebuild if it's hot after a drive."}], "c": {"level": "community", "n": 3, "note": "Standard practice."}}, "aftercare": ["Write the date on a bit of tape on the reservoir.", "Firm pedal after the first drive: done. Soft pedal: bleed again in the same order; if still soft, the ABS unit has air and needs a scan-tool bleed."], "disagreements": [{"topic": "Bleed order", "pos": "VW manual: FL, FR, RL, RR. Pelican and general practice: RR, LR, RF, LF.", "call": "The manual. The ABS unit's layout is the reason, and VW says 'proper bleeding cannot be ensured' otherwise."}, {"topic": "Bleeder pressure", "pos": "10 psi vs 2 bar (30 psi).", "call": "10–15 psi."}], "sources": ["VWVortex threads quoting the Mk5 repair manual bleed sequence", "MicksGarage Project GTI bleeding write-up", "Pelican Parts Mk5 GTI bleeding article", "DAP Mk5 service schedule", "Passat B6 (same platform) bleed procedure"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('brake-lines-ss',$j${"id": "brake-lines-ss", "title": "Stainless brake lines", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI · 3.2 R32", "heroId": "bleed-order", "alsoFits": "All Mk5 platform cars", "category": "Brakes", "kind": "upgrade", "glance": {"timeFirst": "2 hr", "timeRepeat": "1 hr", "difficulty": 2.5, "cost": "$100–180 for four", "risk": "Fluid on paint · line routing · full bleed required", "why": "The rubber hoses at each wheel swell a little every time you press the pedal. Braided stainless lines don't, so the pedal feels firmer and more consistent, especially when the fluid's hot. It's the same job as replacing tired rubber hoses, just with a better part.", "note": "Two hours including the flush that has to follow. The lines themselves are ten minutes a corner."}, "heroCap": "Each corner has one flexible hose from the hard line on the body to the caliper. Swap the hose, then bleed in VW's order.", "lifespan": {"title": "When owners do this", "headline": ["Usually with a pad/rotor upgrade or when a rubber hose shows cracks, often past 100,000 miles"], "earliest": null, "detail": "Rubber hoses don't have a factory replacement interval but they age: surface cracks, bulging under pressure, or a hose that's soft to squeeze means it's overdue. Owners fit stainless at that point because the price gap is small.", "factors": ["Track days", "Rubber hoses cracked or bulging", "Doing a brake flush anyway"], "inspect": ["Every fluid flush: squeeze and look at each hose"], "confidence": {"level": "community", "n": 3, "note": "Forum consensus; no factory interval."}}, "should": {"yesIf": ["Pedal feels soft or inconsistent when hot", "Rubber hoses are cracked, bulging, or original at 100k+", "You're flushing the fluid anyway", "You want the last bit of pedal feel from a pad upgrade"], "codes": [], "notes": ["Buy DOT-compliant lines from a real brand with a PTFE core and a protective outer sleeve. The cheap unbranded sets are the one place in this app where 'aftermarket' can mean 'worse than stock'."], "confidence": {"level": "medium", "n": 3, "note": "Rationale and method consistent; no factory torque for the fittings was found this pass."}}, "parts": [{"tier": "aftermarket", "name": "Stainless brake line set (4)", "pn": "see options below", "note": "Front and rear, with new banjo bolts and copper washers if the kit includes them", "price": "$100–180", "links": []}, {"tier": "oe", "name": "DOT 4 fluid, 1.5 L", "pn": "—", "note": "Full flush follows", "price": "$25–40", "links": []}, {"tier": "oe", "name": "Copper crush washers for banjo fittings", "pn": "if not in kit", "note": "Never reuse", "price": "$5", "links": []}], "aftermarket": [{"name": "StopTech / Goodridge G-Stop", "note": "DOT-compliant, PTFE core, colour sleeve, all clips and washers. The two names the forums trust.", "price": "$120–180", "signal": "Forum favorite", "links": []}, {"name": "ECS / USP stainless kits", "note": "Same construction, often bundled with a fluid flush kit.", "price": "$100–150", "signal": "Value pick", "links": []}], "tools": [{"name": "11mm flare-nut wrench (hard-line unions) and 14mm/17mm for banjo bolts; 11mm for bleeders"}, {"name": "Pressure bleeder, hose, catch bottle, turkey baster"}, {"name": "Line clamp or a bag over the reservoir to slow the drip while a line is off; rags; water spray"}], "before": ["Flare-nut wrench only on the hard-line unions; an open-end wrench rounds them and then you're replacing hard lines.", "One corner at a time, and cap or plug the open hard line to slow the drip.", "Everything gets bled afterwards, in VW's order."], "steps": [{"n": 1, "title": "Wheels off, find the hose", "blocks": [{"t": "text", "b": "Four stands, wheels off. At each corner: a rubber hose from a bracket on the body/strut (hard-line union, 11mm flare nut) to the caliper (banjo bolt or threaded fitting)."}]}, {"n": 2, "title": "Slow the flow", "blocks": [{"t": "text", "b": "Suck the reservoir down near MIN and put a plastic bag under the cap to seal it; the system will barely drip with a line open. Don't clamp the old rubber hose with pliers if you plan to keep it; you don't, so a hose clamp is fine."}]}, {"n": 3, "title": "Swap the line", "caution": true, "blocks": [{"t": "text", "b": "Flare-nut wrench on the hard-line union, back it off, pull the retaining clip and free the hose from the bracket. At the caliper, remove the banjo bolt (or unscrew the fitting). Fit the new line the same way round, new copper washers either side of the banjo, thread the hard-line union by hand first, then snug. Clip the line into the bracket."}, {"t": "warn", "b": "Route the new line exactly where the old one ran and turn the steering lock to lock (front) and bounce the suspension to confirm it can't touch the wheel, spring or strut at any angle. A stainless line rubbing a wheel wears through."}, {"t": "torque", "label": "Banjo bolt / hard-line union", "nm": 15, "alt": [35], "c": {"level": "single", "n": 1, "note": "No factory figure found this pass. Kit sheets range from 15 Nm (union) to 35 Nm (banjo). Snug, then check for weeping under pressure."}}]}, {"n": 4, "title": "Repeat at every corner", "blocks": [{"t": "text", "b": "Same at the other three. Keep the reservoir from running dry."}]}, {"n": 90, "title": "Set up the pressure bleeder", "blocks": [{"t": "text", "b": "Turkey-baster the old fluid out of the reservoir down to the minimum line and refill with fresh DOT 4 from a sealed bottle. Screw the bleeder cap onto the reservoir and pump it to 10–15 psi. Keep the reservoir topped the whole time; if it runs dry the ABS unit takes in air and only a scan tool can bleed it."}, {"t": "warn", "b": "Brake fluid strips paint in minutes. Cover the fender and wing, keep a spray bottle of water handy, and wipe drips immediately."}]}, {"n": 91, "title": "Bleed in the manual's order", "caution": true, "blocks": [{"t": "text", "b": "Manual car first: 11mm on the clutch slave bleeder (on the bell housing), let 50 ml run, close, pump the clutch pedal 10–15 times, open again for another 50 ml, close. Then the brakes: front-left, front-right, rear-left, rear-right. Yes, front first; the ABS unit's layout makes the usual furthest-first rule wrong on this car. At each caliper: dust cap off, 11mm wrench on the nipple, hose into a catch bottle, open until the fluid runs clear and bubble-free, close, cap."}, {"t": "ill", "id": "bleed-order", "cap": "The order VW specifies. Clutch slave first on a manual."}, {"t": "note", "b": "Finishing touch owners swear by: after the pressure bleed, have a helper do five firm pedal strokes per caliper (open the nipple with the pedal down, close before it comes up) to chase any last air."}]}, {"n": 92, "title": "Close up and test", "blocks": [{"t": "text", "b": "Release bleeder pressure, remove the cap, set the reservoir level between the marks (not above MAX; the pads will wear and the level will rise as they're changed). Pedal should be firm within the first inch. Drive gently around the block, brake progressively harder, and check every bleeder for weeping."}]}], "alsoReplace": [{"name": "Pads and rotors", "why": "Same wheels-off session; see those guides."}, {"name": "Clutch line (manual)", "why": "Stainless clutch line is the same idea for a firmer clutch pedal and lives on the same reservoir."}], "check": {"tab": "Rubber or steel?", "title": "Is it worth it on a street car?", "illId": "bleed-order", "illCap": "The gain is consistency, not stopping distance.", "rows": [{"see": "Stock pads, daily driving", "means": "You'll notice a slightly firmer pedal, mostly at first.", "do": "Do it when the rubber hoses need replacing anyway."}, {"see": "Performance pads, spirited driving", "means": "Pedal feel under heat is where stainless shows.", "do": "Yes, with a full flush and good fluid."}, {"see": "Track days", "means": "Consistency lap to lap.", "do": "Yes, with TYP200 or RBF600."}], "c": {"level": "community", "n": 3, "note": "Forum consensus."}}, "aftercare": ["Check every fitting for weeping after the first hard stops.", "Re-check routing after a week: nothing should show rub marks."], "disagreements": [{"topic": "Fitting torque", "pos": "No factory value found; kits vary.", "call": "Snug and leak-check. Flagged single-source."}, {"topic": "Worth it on a stock car?", "pos": "Forum split.", "call": "When the rubber hoses are due anyway, yes."}], "sources": ["Brake bleeding sources (see flush guide)", "StopTech / Goodridge / ECS product listings", "Forum threads on hose ageing and routing"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('dsg',$j${"id": "dsg", "title": "DSG fluid & filter service", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI · 3.2 R32 · 6-speed DSG (02E / DQ250)", "heroId": "dsg-hero", "alsoFits": "Every 6-speed wet-clutch DSG (02E/0D9) 2005–2019: Golf, GTI, Jetta, Eos, Passat, A3, TT", "category": "Drivetrain", "kind": "repair", "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2.5, "cost": "$120–180", "risk": "Fluid level is set by temperature; get it wrong and the box shifts badly", "why": "The DSG's wet clutches and mechatronic unit live in this oil. It shears and fills with clutch material, and VW's 40,000-mile interval is not a suggestion: neglected fluid is behind most of the harsh-shift and mechatronic stories. This service is cheap and very doable at home.", "note": "An afternoon. The only fiddly part is setting the level at the right temperature."}, "heroCap": "Drain plug and overflow tube underneath; filter under a cap on top. The level is set by letting excess run out of the overflow tube with the engine running and the fluid at 35–45°C.", "lifespan": {"title": "When to expect it", "headline": ["Every 40,000 miles, per the factory schedule"], "earliest": "Sooner (30k) if tuned, towing, or tracked", "detail": "Owners who go long describe shudder on take-off, clunky low-speed shifts and hesitation in reverse. Fresh fluid often clears mild versions of these; it won't fix a worn mechatronic unit, but it's the first thing to do.", "factors": ["Tune (more torque through the clutches)", "Stop-and-go city driving", "Unknown history on a used car"], "inspect": ["Nothing to inspect between services; just do it on time"], "confidence": {"level": "high", "n": 4, "note": "Factory interval confirmed by three vendor sources; symptoms are forum consensus."}}, "should": {"yesIf": ["40,000 miles since the last service, or unknown", "Shudder on take-off, harsh or lazy low-speed shifts", "You just bought the car", "You've tuned it"], "codes": [], "notes": ["Fluid spec is VW TL 521 82 (G 052 182 A2). Nothing else. The dual clutches run in this oil and the friction spec matters.", "Filter part is 02E 305 051 C; the cap o-ring comes with a good kit.", "R32: the same 02E DSG in its 4Motion form. Same fluid, filter, capacity and level-set. The Haldex unit behind it has its own service (see the Haldex guide)."], "confidence": {"level": "high", "n": 4, "note": "Spec, capacity and interval agree across all sources."}}, "parts": [{"tier": "oe", "name": "DSG fluid, 6 × 1 L", "pn": "G 052 182 A2", "note": "Service fill is 5.2 L; buy six so the level-set doesn't run short", "price": "$90–120", "links": []}, {"tier": "oe", "name": "DSG filter with o-ring", "pn": "02E 305 051 C", "note": "", "price": "$30–45", "links": []}, {"tier": "oe", "name": "Drain plug crush washer", "pn": "in most kits", "note": "", "price": "$3", "links": []}], "aftermarket": [{"name": "Ravenol DCT/DSG, Eurol DCF 1404, Pentosin FFL-2", "note": "Third-party fluids that meet TL 521 82. Fine; the OE fluid is also made by a third party.", "price": "$15–20 / L", "signal": "Meets spec", "links": []}, {"name": "Blauparts / FCP Euro service kits", "note": "Fluid, filter, washer and the fill adapter in one box.", "price": "$130–180", "signal": "One-box pick", "links": [{"store": "FCP Euro DIY", "url": "https://www.fcpeuro.com/blog/vw/audi-dsg-automatic-transmission-service-diy"}]}], "tools": [{"name": "14mm hex bit (drain plug), 8mm hex bit (overflow tube), 24mm socket or filter socket (filter cap)"}, {"name": "DSG fill adapter (VAS 6262-style) with hose and pump, or a fluid transfer pump into the drain hole"}, {"name": "VCDS or a scan tool that reads transmission fluid temperature; an infrared thermometer as a fallback"}, {"name": "Drain pan ≥ 6 L, torque wrench to 45 Nm, ramps or four stands: the car must be level"}], "before": ["The car must be level for the level-set. Four stands or ramps at both ends.", "Fluid should be warm but not hot when you drain: a short drive, then let it sit 10 minutes.", "Read the level-set step twice before you start. It's the whole job."], "steps": [{"n": 1, "title": "Level, warm, belly pan off", "blocks": [{"t": "text", "b": "Car level on stands, belly pan off. Drain pan under the transmission's bottom plug."}]}, {"n": 2, "title": "Drain", "blocks": [{"t": "text", "b": "14mm hex: remove the drain plug. Fluid runs. When it slows, 8mm hex into the overflow tube inside the drain hole and unscrew it: another litre or so drops. Expect about 5 litres total; measure it roughly so you know what to put back."}, {"t": "ill", "id": "dsg-hero", "cap": "Plug, then the tube inside it. The tube's height is what sets the level later."}]}, {"n": 3, "title": "Filter", "blocks": [{"t": "text", "b": "Top of the transmission, under the airbox/battery area: the round filter cap. 24mm socket, unscrew, lift out the filter (fluid will follow; rag ready). New o-ring on the cap, new filter in, cap on."}, {"t": "torque", "label": "Filter cap", "nm": 20, "c": {"level": "medium", "n": 2, "note": "20 Nm (15 lb-ft) from two owner guides. Plastic cap: snug."}}]}, {"n": 4, "title": "Overflow tube back, fill", "blocks": [{"t": "text", "b": "Overflow tube back in (3 Nm, barely more than finger tight). Thread the fill adapter into the drain hole and pump in about 5 litres, shaking each bottle first. Leave the adapter on."}, {"t": "torque", "label": "Overflow tube (8mm hex)", "nm": 3, "c": {"level": "single", "n": 1, "note": "From the Mk5 FAQ procedure. Plastic; snug."}}]}, {"n": 5, "title": "Set the level", "caution": true, "blocks": [{"t": "text", "b": "Start the engine with the adapter connected and the pan underneath. Foot on the brake, move the lever through P–R–N–D–S, holding each about 3 seconds, back to P. Watch the fluid temperature on VCDS (Auto Trans, measuring block 19) or an IR gun on the pan. Between 35 and 45°C, open the adapter's valve (or remove the adapter and let the drain hole weep). Excess fluid runs out of the overflow tube: expect half a litre to three-quarters. When it slows to a drip, remove the adapter and fit the plug with a new washer."}, {"t": "warn", "b": "Do not let it go past 45°C with the plug out, and do not switch the engine off with the plug out. Hot fluid has expanded and the level will be set low; a stopped engine dumps the fluid held in the box. If more than a litre runs out, stop and reassess: something's wrong with the fill."}, {"t": "torque", "label": "Drain plug (14mm hex)", "nm": 45, "c": {"level": "high", "n": 3, "note": "45 Nm across FCP Euro, the Mk5 FAQ and Blauparts."}}]}, {"n": 6, "title": "Adaptation and test drive", "blocks": [{"t": "text", "b": "Engine off, belly pan on. Many owners run the DSG basic-settings adaptation in VCDS after a service; it's optional but helps if shifts were harsh. Drive it. Check around the filter cap and plug for leaks when you get back."}]}], "alsoReplace": [{"name": "Engine air filter", "why": "The airbox is in your way for the filter cap anyway."}, {"name": "Haldex/other fluids", "why": "Not on a GTI. On an R32 or Golf R the Haldex service shares the afternoon."}], "check": {"tab": "Read the fluid", "title": "What came out?", "illId": "dsg-hero", "illCap": "Fresh DSG fluid is pale amber and thin.", "rows": [{"see": "Amber, clean, smells like oil", "means": "On schedule.", "do": "Normal service."}, {"see": "Dark brown, opaque, burnt smell", "means": "Long overdue; clutch material in suspension.", "do": "Service now; consider a second change after 5–10k to dilute what's left."}, {"see": "Metal glitter or chunks on the magnet", "means": "Mechanical wear, not just old fluid.", "do": "Service, then a transmission specialist. Fluid won't fix this."}], "c": {"level": "community", "n": 3, "note": "Forum consensus."}}, "aftercare": ["Re-check the plug and filter cap for leaks after a day.", "Shifts may feel different for a few drives while the mechatronics adapt.", "Note the mileage; next in 40k."], "disagreements": [{"topic": "How to read the temperature", "pos": "VCDS measuring block vs an IR gun on the pan.", "call": "VCDS if you have it; the IR gun works on the pan and is what two vendor guides use."}, {"topic": "How much fluid", "pos": "5.2 L (spec) vs 5.5 L (FAQ fill).", "call": "Buy six litres; the overflow sets the level."}, {"topic": "Drain plug bit", "pos": "14mm hex (four sources) vs 14mm triple-square (one).", "call": "Hex."}], "sources": ["FCP Euro DSG service DIY (02E)", "Blauparts DSG articles (capacity, spec, interval)", "VWVortex 'DSG Fluid and Filter Technical Write-Up' / Mk5 FAQ", "Pelican Parts Mk5 GTI DSG article", "Golfmk7 DSG DIY and UroTuning guide (torques)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('sway-front',$j${"id": "sway-front", "title": "Front sway bar upgrade", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI · 3.2 R32", "alsoFits": "2006–09 GTI/Rabbit · 05–10 Jetta · 06–08 A3 8P · Mk6 GTI/Golf (same PQ35 front subframe)", "category": "Suspension", "kind": "upgrade", "variants": {"question": "How far do you want to take it apart?", "hint": "The bar hides behind the subframe, so the subframe has to come down either way. Owners mostly lower it a few inches and unbolt the steering rack from it. Manufacturer instructions drop it further and also disconnect the steering column, ball joints and tie rods.", "options": [{"id": "partial", "label": "Partial lower (owner method)", "when": "Fewer parts touched, tighter to work in. Recommended for a driveway."}, {"id": "full", "label": "Full drop (manufacturer method)", "when": "More room, more disconnecting, steering-column care needed. Best on a lift."}]}, "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr with a lift and a helper", "difficulty": 4, "cost": "$250–450 + alignment", "risk": "Subframe on a jack · single-use stretch bolts · alignment afterwards", "why": "The rear bar changed the car's balance. The front bar is about grip: less roll means the outside front tire stays flatter on the road, so a strut car like this one stops giving away camber mid-corner.", "note": "One vendor calls this 'easy'. Every owner account says three hours, two people, and an alignment. Believe the owners."}, "heroCap": "The bar sits in the channel between the subframe and the steering rack. There is no way to get it out without lowering the subframe.", "lifespan": {"title": "When owners do this", "headline": ["Usually after the rear bar and tires, before or with coilovers"], "earliest": null, "detail": "The stock bar doesn't wear out. Owners add a front bar when they've already done the rear and want the front to stop washing out, or as part of a bigger suspension job while the subframe is already down.", "factors": ["Rear bar already installed", "Coilovers or lowering springs going in", "Track days"], "inspect": ["While the subframe is down: dogbone (pendulum) mount bushing and front control-arm bushings are worth a look"], "confidence": {"level": "community", "n": 5, "note": "Forum consensus on ordering. Which bar is a preference."}}, "should": {"yesIf": ["You've done the rear bar and the front still pushes wide", "You want flatter cornering without harsher ride", "You're already dropping the subframe for something else", "You have a torque wrench that does angle, or a patient helper and a marker"], "codes": [], "notes": ["A stiffer front bar on a front-driver sounds like it should add understeer. In practice it reduces body roll, which keeps the loaded front tire upright, so it usually adds front grip rather than taking it away. Rear bar first, then front, is the order almost everyone lands on.", "This is the most involved job in the app so far. Nothing is dangerous once the car is on stands, but a subframe on a floor jack wants a second person, and the alignment afterwards is not optional.", "R32: same subframe and procedure; buy the R32-rated bar."], "confidence": {"level": "high", "n": 6, "note": "Method and rationale agree across the manufacturer guide, four forum DIYs, and a magazine test."}}, "parts": [{"tier": "aftermarket", "name": "Front sway bar kit (bar, poly bushings, brackets, grease)", "pn": "see options below", "note": "Most kits include the stretch bolts you need; check yours", "price": "$250–400", "links": []}, {"tier": "oe", "name": "Subframe & control-arm bolts, M12 (×6)", "pn": "single-use", "note": "Stretch bolts. Every source says replace", "price": "$30–50", "links": []}, {"tier": "oe", "name": "Steering rack bolts, M10 (×4)", "pn": "single-use", "note": "Also stretch bolts", "price": "$15", "links": []}, {"tier": "oe", "name": "Pendulum (dogbone) mount bolts", "pn": "single-use", "note": "Two into the transmission", "price": "$10", "links": []}, {"tier": "oe", "name": "End-link nuts (×2)", "pn": "self-locking", "note": "Replace whenever removed", "price": "$4", "links": []}, {"tier": "oe", "name": "Steering shaft u-joint bolt", "pn": "single-use", "note": "Full-drop method only", "price": "$5", "links": [], "only": ["full"]}], "aftermarket": [{"name": "ECS Tuning 26mm", "note": "Solid, non-adjustable, comes with poly bushings, all stretch bolts and subframe spacer plates. The install PDF is the most complete one available.", "price": "$300", "signal": "Best documented", "links": [{"store": "ECS Tuning install PDF", "url": "https://assets.ecstuning.com/edoc/PDF_9205_Volkswagen_MK5-MK6_ECS_Front_Sway_Bar_Installation.pdf"}]}, {"name": "H&R 26mm", "note": "Tubular, non-adjustable, rubber-lined bushings that need no greasing. The bar the 2008 owner DIYs were written around.", "price": "$250–300", "signal": "Forum favorite", "links": []}, {"name": "034Motorsport adjustable", "note": "Two-hole adjustable, billet brackets. Grassroots Motorsports ran it on the soft setting and set a personal best.", "price": "$350–450", "signal": "Track-leaning pick", "links": []}, {"name": "APR / Hotchkis", "note": "Same bar under two names. Instructions insisted on load on the wheels throughout; owners found that only matters for the end links.", "price": "$300–350", "signal": "Fine, with that caveat", "links": []}], "tools": [{"name": "Floor jack + two stands, plus a second jack (or transmission jack) for the subframe", "note": "A board on the jack pad spreads the load"}, {"name": "Sockets: 13, 16, 17, 18, 21mm · ½\" breaker bar", "note": "The 21mm subframe bolts are very tight"}, {"name": "6mm triple-square or 5mm hex (end links) · T20/T25 Torx (belly pan)"}, {"name": "Torque wrench that reads to 120 Nm, and an angle gauge (or a marker for the +90° turns)"}, {"name": "Pry bar, penetrating oil, wire brush, marker or paint pen for reference marks"}, {"name": "Angle grinder (optional)", "note": "Owners cut the hollow stock bar in two rather than wrestle it out", "only": ["partial"]}], "before": ["Level ground. Stands on the body jack points, never under the subframe you're about to drop.", "Raise both sides of the front together; one side up puts the bar under load.", "Mark the subframe's position on the body with a paint pen before a single bolt comes out. Its outline (the 'footprint') is your only alignment reference.", "Book an alignment for afterwards. Subframe position sets toe and camber; you will not get it back exactly by eye.", "Full-drop method: park with the steering wheel dead straight and keep it there. Rotating the wheel with the column disconnected can damage the airbag clockspring."], "steps": [{"n": 1, "title": "Steering shaft (full drop only)", "only": ["full"], "blocks": [{"t": "text", "b": "Inside the car, remove the two 13mm fasteners on the steering-shaft cover at the pedals and lift it off. Remove the u-joint bolt where the shaft meets the rack and slide the joint up off the rack. It's a single-use bolt."}, {"t": "warn", "b": "From this point until the joint is back on, nobody turns the steering wheel. A rotated clockspring is an airbag light at best."}]}, {"n": 2, "title": "Raise the front, wheels off, belly pan off", "blocks": [{"t": "text", "b": "Loosen the lug bolts (17mm) on the ground, raise both sides, stands under the body. Wheels off. Remove the plastic belly pan or insulation tray (T20/T25) so you can see the subframe."}]}, {"n": 3, "title": "Disconnect the end links from the bar", "blocks": [{"t": "text", "b": "18mm nut on each link at the bar. If the stud spins, hold it with a 6mm triple-square (some links: 5mm hex) and turn the nut. They're often seized: wire-brush the exposed thread, soak with penetrating oil, and work the nut back and forth. Don't heat them; the joint boot won't survive it."}, {"t": "ill", "id": "fsb-endlink", "cap": "Stud held, nut turned. Same technique front and rear."}]}, {"n": 4, "title": "Headlight level sensor (if you have HIDs)", "blocks": [{"t": "text", "b": "Driver's side, above the lower control arm: unplug the sensor and unbolt its arm bracket from the arm (10mm). Note which way the joint points so it goes back the same."}]}, {"n": 5, "title": "Ball joints and tie rods (full drop only)", "only": ["full"], "blocks": [{"t": "text", "b": "Remove the three 16mm ball-joint nuts each side and pull the control arm down off the joint; a pry bar between them if they're corroded together. Remove both outer tie-rod nuts (18mm) and pop the tie rods out of the bearing housings with a separator, or a sharp hammer blow to the housing."}]}, {"n": 6, "title": "Unbolt everything hanging on the subframe", "blocks": [{"t": "text", "b": "Two exhaust hanger bolts at the rear of the subframe (13mm). The four steering-rack bolts (13mm), two per side, where the rack sits on the subframe. The four sway-bar bracket bolts (13mm)."}, {"t": "text", "b": "Pendulum (dogbone) mount: two bolts into the transmission (16mm) and, on the partial method, the two into the subframe (13mm) so the mount comes free.", "only": ["partial"]}, {"t": "text", "b": "Pendulum mount: remove the two bolts into the transmission (16mm).", "only": ["full"]}]}, {"n": 7, "title": "Jack under the subframe, then the big bolts", "caution": true, "blocks": [{"t": "text", "b": "Second jack (with a board) snug under the middle of the subframe. Now the six 18mm/21mm subframe and control-arm bolts: two long ones at the rear, two at the rear control-arm brackets, two forward ones hidden behind the control arms (socket on a 6-inch extension). Loosen the forward pair first; remove them last."}, {"t": "warn", "b": "The subframe is heavy and the jack is the only thing holding it. Have your helper steady it from here on. Never put any part of you under it."}, {"t": "torque", "label": "Subframe & control-arm bolts (M12, on reassembly)", "nm": 70, "c": {"level": "varies", "n": 2, "note": "Manufacturer: 70 Nm + 90°. Owner table: 70 Nm (52 lb-ft) + 45°. Same base value; the angle differs. We show the manufacturer's."}, "note": "+90° turn"}]}, {"n": 8, "title": "Lower the subframe", "blocks": [{"t": "text", "b": "Lower the jack slowly and evenly, about four inches, watching the steering rack: it needs to lift off its dowel pins and come free of the subframe. A screwdriver under the rack helps release the pins. The rack stays connected to the column and just hangs.", "only": ["partial"]}, {"t": "text", "b": "Lower the jack a little at a time. As soon as you can reach it, remove the hidden 10mm bolt holding the steering-rack wiring harness to the rack (driver's side, inside the subframe) and release the harness clip a few inches along. Then lower until the bar is fully exposed, and lift the rack slightly rearward off its dowel pins.", "only": ["full"]}, {"t": "ill", "id": "fsb-drop", "cap": "Subframe on the jack, lowered. The bar comes out over the passenger side of the subframe, forward and down, while the driver's end threads between the subframe and rack."}]}, {"n": 9, "title": "Get the old bar out", "timeSink": true, "blocks": [{"t": "text", "b": "Lift the bar up and over the passenger-side subframe arm, bring it forward and down, and guide the driver's end between the subframe and the rack. Two people, some swearing, several attempts. The bushings snag on the rack; snapping the old brackets off the bar first helps."}, {"t": "note", "b": "Owner shortcut: with the bar still bolted in, cut it in half with a grinder. The stock bar is hollow and goes quickly. Eye protection; you're on your back under sparks. Then each half comes out easily.", "only": ["partial"]}]}, {"n": 10, "title": "Bushings and brackets onto the new bar", "blocks": [{"t": "text", "b": "Grease the inside of poly bushings with the kit's grease (never petroleum grease; never any grease on factory rubber bushings). Slide them on against the stops. Lower brackets under, uppers on top, raised face up, bolt holes outboard. Some kits fit the brackets loosely at this point; others want them fully seated. Follow the kit sheet."}]}, {"n": 11, "title": "Feed the new bar in", "blocks": [{"t": "text", "b": "Reverse of removal: driver's end between rack and subframe first, then lift the passenger end over. Set the bar in front of the rack. Adjust the rack's position as needed so the bar drops into place."}]}, {"n": 12, "title": "Raise the subframe and start every bolt by hand", "caution": true, "blocks": [{"t": "text", "b": "Raise the jack until the subframe meets the body. Seat the steering rack onto its dowel pins first; if it isn't fully seated you'll end up with a loose rack. Then start, by hand and loosely, in this order: rear control-arm bolts, the four rack bolts, the four sway-bar bracket bolts, forward subframe bolts, then the two long rear subframe bolts. Full-drop: reconnect the harness clip and its 10mm bolt as the subframe comes up.", "only": ["partial", "full"]}, {"t": "text", "b": "Kits that supply subframe spacer plates: they go between the subframe and body at the rear mounts. Fit them whether or not the car had them.", "only": ["partial", "full"]}, {"t": "text", "b": "Now align. Nudge the subframe until every bolt hole lines up with your paint marks and the footprint. Loosen the 'horns' and rear brackets if it won't move; snug bolts fight you. Only when everything lines up do you tighten anything."}, {"t": "warn", "b": "Tighten nothing to torque until all fourteen bolts are started and the subframe is on its marks. One bolt torqued early locks the subframe in the wrong place and you'll be doing this again after the alignment shop calls."}, {"t": "torque", "label": "Steering rack bolts (M10)", "nm": 50, "c": {"level": "varies", "n": 2, "note": "Manufacturer 50 Nm + 90°; owner table 37 lb-ft + 45°. Same base value."}, "note": "+90° turn"}, {"t": "torque", "label": "Sway bar bracket bolts (M8)", "nm": 20, "c": {"level": "varies", "n": 2, "note": "Manufacturer 20 Nm + 90°; owner table 15 lb-ft + 45°."}, "note": "+90° turn"}, {"t": "torque", "label": "Pendulum mount bolts", "nm": 40, "alt": [50], "c": {"level": "medium", "n": 2, "note": "40 Nm for 8.8-grade bolts, 50 Nm for 10.9-grade, each + 90°. Check the number stamped on the bolt head."}, "note": "+90° turn"}, {"t": "ill", "id": "fsb-bolts", "cap": "Order matters: seat the rack, start everything loose, align to your marks, then torque. Subframe and arm bolts get their angle last."}]}, {"n": 13, "title": "Reconnect the rest", "blocks": [{"t": "text", "b": "Exhaust hanger back on the subframe. Ball joints: three nuts each side, 60 Nm for a cast arm or 100 Nm for an aluminium/sheet-steel arm. Tie rods: 20 Nm + 90°. Level sensor arm and plug.", "only": ["full"]}, {"t": "text", "b": "Exhaust hanger back on the subframe. Level sensor arm and plug.", "only": ["partial"]}, {"t": "text", "b": "Steering shaft: seat the u-joint back on the rack and torque the new bolt to 30 Nm. Only now may the wheel turn.", "only": ["full"]}]}, {"n": 14, "title": "End links, on the ground", "blocks": [{"t": "text", "b": "Pass the studs through the bar's holes (adjustable bars: start on the softer, outer hole), start new self-locking nuts. Wheels on, torque to 120 Nm, lower the car. Then torque the end-link nuts with the car on its wheels so the links aren't preloaded."}, {"t": "torque", "label": "End-link nuts (M10)", "nm": 65, "c": {"level": "high", "n": 3, "note": "65 Nm / 48 lb-ft agrees across the manufacturer guide, an MQB guide and a forum torque thread."}}]}, {"n": 15, "title": "Alignment, then re-check", "blocks": [{"t": "text", "b": "Drive gently to the alignment shop. Tell them the subframe was lowered. After 50 miles, re-check the end links and that nothing clunks over one-wheel bumps."}]}], "alsoReplace": [{"name": "Pendulum (dogbone) mount insert or bushing", "why": "It's unbolted anyway, and a tired one is the usual source of drivetrain clunk on these cars. A poly insert is $30 and ten minutes here versus an hour on its own."}, {"name": "Front sway-bar end links", "why": "They're off. If the boots are cracked or the joints have play, new ones now save a second trip under the car."}, {"name": "Subframe alignment (Deadset-style) kit", "why": "Replaces the subframe's slop with locating sleeves so it can't shift under load. Only sensible while the bolts are already out."}], "check": {"tab": "Pick a setting", "title": "Which hole, if your bar is adjustable?", "illId": "setting", "illCap": "Same logic as the rear bar: the hole closer to the pivot is stiffer.", "rows": [{"see": "Street car, all-season or touring tires", "means": "You want the roll reduction without changing balance much.", "do": "Softer (outer) hole. Most stay here."}, {"see": "Summer tires, already on the stiff rear setting", "means": "The car may have gone tail-happy; the front bar brings balance back.", "do": "Softer hole first, evaluate, then stiffer if the front still rolls more than the rear."}, {"see": "Track use", "means": "You'll tune front and rear together per event.", "do": "Stiffer hole, adjustable end links front and rear."}], "c": {"level": "community", "n": 3, "note": "Forum consensus plus one magazine test (fastest lap on the soft setting)."}}, "aftercare": ["Alignment within the first drive or two. Not optional.", "Re-torque end links after 50 miles.", "Poly bushings squeak when dry; re-grease at the first squeak.", "Clunk from the front on take-off after this job: check the pendulum mount bolts."], "disagreements": [{"topic": "Full drop or partial lower?", "pos": "Manufacturer disconnects steering column, ball joints and tie rods and drops the subframe fully; owners lower it about four inches and unbolt the rack.", "call": "Both work. Partial for a driveway, full on a lift. You choose at the top of the guide."}, {"topic": "+45° or +90° on the stretch bolts?", "pos": "Manufacturer PDF says +90°; the 2008 owner table says +45° on the same base values.", "call": "Manufacturer, since it's current and cites the bolt sizes. The base torque agrees everywhere."}, {"topic": "How hard is it?", "pos": "'Skill Level 1 – Easy' vs. every owner account.", "call": "4 out of 5. Plan a full afternoon and a helper."}, {"topic": "Load on the wheels during install?", "pos": "APR's sheet said keep the car loaded throughout; owners found the subframe wouldn't align that way.", "call": "Unloaded for the subframe and rack; loaded only for the final end-link torque."}], "sources": ["ECS Tuning Mk5/Mk6 Front Sway Bar installation PDF (2019)", "VWVortex 'DIY: Front Sway Bar Install' (2008)", "MyFastGTI 'MK5 Front Swaybar DIY' (2008)", "Pelican Parts front sway bar bushings article", "GolfMKV APR install troubleshooting thread (2013)", "Golfmk6 install threads (2014, 2015)", "Grassroots Motorsports 034 front bar test (2023)"], "embeds": [], "heroId": "fsb-drop"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('endlinks',$j${"id": "endlinks", "title": "Sway bar end links", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI · 3.2 R32", "alsoFits": "2006–09 GTI/Rabbit · 05–10 Jetta · 06–08 A3 · Mk6 GTI/Golf", "category": "Suspension", "kind": "repair", "variants": {"question": "Front or rear?", "hint": "Front links run from the sway bar up to a bracket on the strut. Rear links run from the bar down to the trailing arm. Same technique, different sizes and torque.", "options": [{"id": "front", "label": "Front end links", "when": "18mm nut, 6mm triple-square"}, {"id": "rear", "label": "Rear end links", "when": "16mm nut, 6mm triple-square"}]}, "glance": {"timeFirst": "45 min", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$30–120 a pair", "risk": "Car on stands · seized nuts", "why": "End links are the two little rods that connect the sway bar to the suspension. When their ball joints wear, the bar rattles instead of working, and you hear it as a clunk over every manhole cover.", "note": "Four sources, all under an hour. Seized nuts are the only variable."}, "heroCap": "Front link: bar to strut bracket. Rear link: bar to trailing arm. Each end has a stud with a socket in its tip so you can hold it while the nut turns.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Front links: commonly loose or rattling past 80,000–120,000 miles", "only": ["front"]}, {"text": "Rear links: often still fine past 100,000; check whenever the bar is off", "only": ["rear"]}], "earliest": "Sooner on cars with stiffer aftermarket bars, which load the joints harder", "detail": "The symptom is a hollow clunk or rattle from one corner over small bumps, worst at low speed. Grab the link with the car on stands and wiggle: any play in the joint, or a torn boot, and it's done.", "factors": ["Aftermarket sway bar", "Lowered car (links at an angle)", "Salt-belt corrosion"], "inspect": ["Check whenever you're under the car with a wheel off"], "confidence": {"level": "community", "n": 4, "note": "Owner reports and vendor notes; no factory interval. Mileage is anecdotal."}}, "should": {"yesIf": ["Clunk or rattle from a corner over small bumps", "Visible play when you wiggle the link by hand", "Torn or missing rubber boot on a joint", "You just fitted a stiffer bar and the old links have miles on them"], "codes": [], "notes": ["Both sides. If one has worn, the other is close, and a mismatched pair loads the bar unevenly."], "confidence": {"level": "high", "n": 4, "note": "Symptoms and technique agree across vendor articles and forum threads."}}, "parts": [{"tier": "oe", "name": "Front end link, Genuine/OEM (each)", "pn": "Lemförder, TRW or Meyle HD", "note": "Lemförder is the OE maker", "price": "$25–45", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Rear end link, Genuine/OEM (each)", "pn": "Lemförder or Meyle HD", "note": "", "price": "$20–35", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Self-locking nuts (×4)", "pn": "factory", "note": "Replace every time they come off", "price": "$6", "links": []}], "aftermarket": [{"name": "Adjustable end links (034, Whiteline, SuperPro)", "note": "Let you set the length so the bar sits unloaded at rest, which matters once the car is lowered or the bar is on its stiff setting. Heim-joint types are noisier and want greasing.", "price": "$120–250 a pair", "signal": "Worth it if lowered", "links": []}, {"name": "Moog / heavy-duty fixed links", "note": "Bigger joints than OE at OE length. A common, cheap answer to a rattle on a stock-height car.", "price": "$40–70 a pair", "signal": "Budget pick", "links": []}], "tools": [{"name": "Jack + two stands; 17mm for the lug bolts"}, {"name": "18mm wrench (ratcheting open-end is ideal) and a 6mm triple-square bit", "only": ["front"]}, {"name": "16mm wrench and a 6mm triple-square bit", "only": ["rear"]}, {"name": "Penetrating oil, wire brush, torque wrench to 65 Nm"}], "before": ["Raise both sides of that axle together. One wheel up loads the bar and the links won't come off without a fight.", "Soak the nuts with penetrating oil while you get the wheels off.", "Final torque happens with the car back on its wheels."], "steps": [{"n": 1, "title": "Raise the axle, wheels off", "blocks": [{"t": "text", "b": "Loosen lugs on the ground, raise both sides of the axle, stands under the body, wheels off."}]}, {"n": 2, "title": "Find the link", "blocks": [{"t": "text", "b": "Behind the strut, a short rod from the end of the sway bar up to a bracket on the strut body. Two nuts: one at the bar, one at the strut.", "only": ["front"]}, {"t": "text", "b": "Inboard of the wheel, a short rod from the end of the sway bar down to the trailing arm. Two nuts: one at the bar, one at the arm.", "only": ["rear"]}, {"t": "ill", "id": "fsb-endlink", "cap": "Triple-square in the stud's tip to hold it still; wrench on the nut does the turning."}]}, {"n": 3, "title": "Remove the nuts", "blocks": [{"t": "text", "b": "18mm on the nut. If the whole stud spins, put the 6mm triple-square into the socket in the stud's tip and hold it while you turn the nut. Work a seized nut back and forth rather than forcing it, and re-oil. No heat; the boot won't survive it.", "only": ["front"]}, {"t": "text", "b": "16mm on the nut, 6mm triple-square holding the stud if it spins. Work a seized nut back and forth and re-oil. No heat.", "only": ["rear"]}, {"t": "note", "b": "The bar isn't under load with both wheels up. Nothing springs when the link comes off."}]}, {"n": 4, "title": "Swap the link", "blocks": [{"t": "text", "b": "Pull the old link out, compare lengths with the new one, and fit the new one the same way round. Start new self-locking nuts by hand at both ends. Snug only."}]}, {"n": 5, "title": "Other side", "blocks": [{"t": "text", "b": "Repeat. Both sides, always."}]}, {"n": 6, "title": "Wheels on, car down, then torque", "blocks": [{"t": "text", "b": "Wheels on (120 Nm), lower the car, roll it a foot to settle. Then torque the link nuts with the weight on the wheels so the joints aren't clamped at a strange angle."}, {"t": "torque", "label": "Front end-link nuts", "nm": 65, "c": {"level": "high", "n": 3, "note": "65 Nm / 48 lb-ft: manufacturer guide, MQB guide, forum torque thread."}, "only": ["front"]}, {"t": "torque", "label": "Rear end-link nuts", "nm": 45, "c": {"level": "single", "n": 1, "note": "Factory manual value via a forum thread. Kit hardware may specify less; follow the kit."}, "only": ["rear"]}]}], "alsoReplace": [{"name": "Sway bar bushings", "why": "Rear bushings are two bolts away once the links are off. Front bushings can be swapped without dropping the subframe (Pelican confirms), and a dry rubber bushing is the other source of front-end squeak."}], "check": {"tab": "Is it the link?", "title": "Is the noise really the end link?", "illId": "fsb-endlink", "illCap": "Wiggle test: any play here, or a torn boot, is a bad link.", "rows": [{"see": "Hollow clunk over small bumps, one corner, low speed", "means": "Classic end link. Confirm with the wiggle test.", "do": "Replace both links on that axle."}, {"see": "Creak or groan when turning into a driveway", "means": "More likely the sway bar bushings or a strut top mount.", "do": "Check bushings first; they're cheaper."}, {"see": "Knock on acceleration or gear change", "means": "Drivetrain mount, usually the pendulum (dogbone) mount.", "do": "Different job; see the front sway bar guide's 'while you're in there'."}], "c": {"level": "community", "n": 3, "note": "Forum diagnosis threads plus vendor articles."}}, "aftercare": ["Re-check torque after 50 miles.", "If a new link rattles immediately, the nut was torqued in the air or the link length is wrong for a lowered car."], "disagreements": [{"topic": "Which bit holds the stud?", "pos": "6mm triple-square (most sources), 5mm hex (ECS's own links), '16mm triple-square' (Pelican, clearly a typo).", "call": "6mm triple-square for factory links; check your new links' studs."}, {"topic": "Torque in the air or on the ground?", "pos": "Vendor guides torque on the lift; the factory manual says curb weight.", "call": "On the ground."}, {"topic": "Front torque", "pos": "65 Nm (PQ35/MQB sources) vs 90 Nm (a 2005 thread).", "call": "65. The 90 Nm figure is Mk4."}], "sources": ["ECS Tuning front sway bar PDF", "VWVortex 'Sway Bar Link Replacement?' (2016)", "Pelican Parts drop-link article", "1A Auto Mk5/6 end-link video guide", "IE and Eco-de Tuning MQB guides (technique only)", "TDIClub Bentley torque thread"], "embeds": [], "heroId": "fsb-endlink"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('coilovers',$j${"id": "coilovers", "title": "Coilover install", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI · 3.2 R32", "heroId": "coilover-hero", "alsoFits": "Mk5/Mk6 Golf, GTI, Jetta, Eos · A3 8P (same PQ35 strut and multilink rear)", "category": "Suspension", "kind": "upgrade", "variants": {"question": "Does your kit include its own top mounts?", "hint": "Most European kits (KW, Bilstein, H&R, ST, Koni) reuse the factory strut mounts and bearings, so the old struts have to come apart. Kits with their own mounts or camber plates (BC Racing, some ECS kits) bolt straight in.", "options": [{"id": "reuse", "label": "Reuses factory mounts", "when": "KW, Bilstein, H&R, ST, Koni. Spring compressor needed, or buy new mounts."}, {"id": "own", "label": "Includes top mounts / camber plates", "when": "BC Racing, ECS kits with HD mounts. Stock struts stay assembled."}]}, "glance": {"timeFirst": "6–8 hr (a full day)", "timeRepeat": "4 hr", "difficulty": 3.5, "cost": "$900–2,500 + alignment", "risk": "Compressed springs · seized pinch bolts · axle bolt at 200 Nm · alignment required", "why": "Coilovers replace the springs and dampers at all four corners with adjustable ones: you set the ride height, and on adjustable kits the damping. It's the biggest single change you can make to how the car drives, and the most involved bolt-on in this app after the clutch.", "note": "ECS rates it moderate; owners say a full day, two if a pinch bolt is seized. The alignment afterwards is not optional."}, "heroCap": "Front: strut clamped in the wheel-bearing housing by one pinch bolt, hung from three bolts under the cowl. Rear: separate spring in the control arm and a shock on two upper bolts and one big lower bolt.", "lifespan": {"title": "When owners do this", "headline": ["Usually after sway bars and tires, or when the original dampers are done around 100,000 miles"], "earliest": null, "detail": "Original dampers on a 2006 car are tired by now; a bouncy ride, nose-dive under braking and inner-edge tire wear are the signs. Owners choosing between new factory-style dampers and coilovers usually go coilover because the price gap has closed and the springs come with it.", "factors": ["Worn original dampers", "Sway bars already fitted", "Want the stance"], "inspect": ["Bounce test each corner: more than one rebound means the damper is gone"], "confidence": {"level": "community", "n": 4, "note": "Forum consensus; no factory interval for dampers."}}, "should": {"yesIf": ["Original dampers are worn", "You want adjustable ride height and, on some kits, damping", "Sway bars are done and you want the next step", "You have a full day, a helper for the front struts, and an alignment booked"], "codes": [], "notes": ["Buy the installation kit, or its parts: new strut mounts and bearings, pinch bolts and nuts, axle bolts, rear shock mounts and bolts. Half of these are torque-to-yield and all of them are twenty years old. The kit also saves you a spring compressor if your coilovers reuse factory mounts.", "Lower it sensibly. Below about 1.5 inches of drop on a PQ35 car the geometry goes off, inner tires wear fast, and you'll want camber correction and adjustable end links. Set height for how you drive, not for the photo.", {"text": "Reusing the factory mounts means compressing the old springs to get the mounts off. A spring compressor is the most dangerous tool in a home garage. Rent a good one, use both claws, and never put any part of you in line with the spring.", "only": ["reuse"]}, "R32: kits are R32-specific (heavier nose, different spring rates). The procedure is identical on the PQ35 chassis."], "confidence": {"level": "high", "n": 4, "note": "Procedure agrees across the manufacturer guide and owner DIYs; the parts-replacement advice is universal."}}, "parts": [{"tier": "aftermarket", "name": "Coilover kit (4 corners)", "pn": "see options below", "note": "", "price": "$900–2,500", "links": []}, {"tier": "oe", "name": "Front strut mounts (×2) and bearings (×2)", "pn": "1K0 412 331 B · 6N0 412 249 C", "note": "Old ones are worn and you're compressing springs to reuse them", "price": "$60–120", "links": [], "only": ["reuse"]}, {"tier": "oe", "name": "Front pinch bolts and nuts (×2)", "pn": "M14, torque-to-yield", "note": "Replace", "price": "$15", "links": []}, {"tier": "oe", "name": "Outer axle bolts (×2)", "pn": "24mm 12-point, torque-to-yield", "note": "Replace", "price": "$20", "links": []}, {"tier": "oe", "name": "Rear shock mounts (×2) and upper bolts", "pn": "1K0 513 353 G", "note": "Cheap; replace", "price": "$40", "links": []}, {"tier": "oe", "name": "Alignment", "pn": "—", "note": "Book it for the day after", "price": "$100–150", "links": []}], "aftermarket": [{"name": "KW V1 / V2 / V3", "note": "Stainless bodies, reuse factory mounts. V1 fixed damping, V2 rebound-adjustable, V3 rebound and compression. The reference kit; priced like it.", "price": "$1,400–2,500", "signal": "Reference kit", "links": []}, {"name": "Bilstein B14 (PSS) / B16 (PSS10)", "note": "B14 fixed damping, B16 ten-click adjustable. Reuse factory mounts. Firm, controlled, long-lived.", "price": "$1,200–2,200", "signal": "Daily-and-track pick", "links": []}, {"name": "ST X / XA / XTA", "note": "KW's value brand, same threads and install. XA adds damping, XTA adds camber plates (so it needs no factory mounts).", "price": "$900–1,700", "signal": "Value pick", "links": []}, {"name": "H&R Street Performance", "note": "Reuse factory mounts; comfortable side of the range; H&R's spring rates.", "price": "$1,100–1,500", "signal": "Comfort pick", "links": []}, {"name": "BC Racing BR", "note": "Includes camber plates and top mounts, 30-way damping, rear separate spring perch. No spring compressor needed. Softer bodies; the price shows.", "price": "$1,000–1,300", "signal": "Own mounts included", "links": []}, {"name": "ECS Tuning adjustable kit", "note": "Budget kit; the ECS install PDF this guide follows was written around a similar design. Pair with their install kit.", "price": "$700–900", "signal": "Best documented", "links": [{"store": "ECS install PDF", "url": "http://bd8ba3c866c8cbc330ab-7b26c6f3e01bf511d4da3315c66902d6.r6.cf1.rackcdn.com/PDF_6302_Volkswagen_MK5-6_Coilover_Installation_Instructions.pdf"}]}], "tools": [{"name": "Jack, four stands, a second jack for the control arms; wheel hanger helps"}, {"name": "M14 triple-square (pinch bolt) and M6 triple-square (end links); 24mm 12-point socket and a breaker bar or impact (axle bolt)"}, {"name": "Spindle housing spreader tool", "note": "The strut will not come out of the housing without it; rent or buy (ECS ES#3894)"}, {"name": "Strut nut sockets (21/22mm pass-through) and a 7mm hex to hold the rod; 19mm offset wrench for the rear"}, {"name": "Spring compressor (rent a good one)", "only": ["reuse"]}, {"name": "Sockets 10, 13, 16, 18, 21mm; torque wrench to 200 Nm; angle gauge or paint pen; penetrating oil; tape measure"}], "before": ["Measure fender-to-ground at all four corners on level ground and write it down. It's your only reference for setting height.", "Soak the pinch bolts, axle bolts and end-link nuts the night before.", "Loosen the axle bolts with the wheels on the ground or a helper on the brakes, never with the wheel off the ground and the bearing taking the load.", "Do fronts first (harder), then rears. Both sides of an axle before you move on."], "steps": [{"n": 1, "title": "Measure, raise, wheels off", "blocks": [{"t": "text", "b": "Fender heights recorded. Loosen the two axle bolts (24mm 12-point) with the car on the ground. Raise it on four stands, all wheels off."}]}, {"n": 2, "title": "Front: disconnect around the strut", "blocks": [{"t": "text", "b": "End-link nut at the strut (18mm, M6 triple-square holding the stud). Brake hose and ABS wire bracket bolt (10mm) off the bearing housing; don't stretch the hose. Axle bolt fully out. Driver's side: level-sensor arm bracket off the control arm (10mm). Three ball-joint nuts (16mm), pry the control arm down off the joint, pull the bearing housing outward so the CV joint comes out of the hub, and wire the shaft up. Reconnect the ball joint loosely so the arm is controlled."}, {"t": "ill", "id": "coilover-hero", "cap": "Front strut: one pinch bolt below, three bolts above. The housing has to be spread to release it."}]}, {"n": 3, "title": "Front: pinch bolt and spreader", "caution": true, "blocks": [{"t": "text", "b": "Jack under the control arm. Pinch bolt out: M14 triple-square one side, 18mm the other. Spreader tool into the slot at the back of the bearing housing, rotate it to open the gap, then lower the jack and tap the housing down off the strut with a hammer until it's free."}, {"t": "warn", "b": "A seized pinch bolt is where the day goes. Heat, oil and patience; if the triple-square rounds, you're drilling. Never hammer the housing without the spreader in; the aluminium cracks."}]}, {"n": 4, "title": "Front: strut out from the top", "blocks": [{"t": "text", "b": "Peel back the cowl seal at the strut tower to reach the three 13mm top bolts. One hand on the strut, remove all three, and lower it out of the car."}]}, {"n": 5, "title": "Front: strip the old mounts", "only": ["reuse"], "caution": true, "blocks": [{"t": "text", "b": "Old strut in a vise. Spring compressor on, both claws, compressed until the spring lifts off the upper seat. Hold the rod with a 7mm hex, remove the top nut with a 21mm strut socket, lift the mount and bearing off. Release the compressor slowly. Inspect: if the bearing is notchy or the mount's rubber is cracked, use new ones instead."}, {"t": "warn", "b": "A compressed coil spring stores enough energy to kill. Claws seated, hooks facing each other, never over the ends of the spring. Do this on the bench, never in the car."}]}, {"n": 6, "title": "Front: build the coilover", "blocks": [{"t": "text", "b": "Light grease on the threads. Perch and lock ring threaded to the bottom. Spring on, kit's upper spacer, then the mount and bearing (new, or the factory ones you just freed). Arrows or marks on the mount point fore and aft. New top nut, rod held with a 7mm hex.", "only": ["reuse"]}, {"t": "text", "b": "Light grease on the threads. Perch and lock ring to the bottom, spring on, then the kit's top mount or camber plate per its sheet: camber plates have a marked orientation and an adjustment slot that should start centred. New top nut, rod held with a hex.", "only": ["own"]}, {"t": "torque", "label": "Front strut top nut", "nm": 60, "c": {"level": "high", "n": 2, "note": "60 Nm from the manufacturer guide and the Koni owner DIY. Kit-supplied nuts may differ; check."}}, {"t": "text", "b": "Wind the perch up until the spring just touches both seats. Height comes later."}]}, {"n": 7, "title": "Front: into the car", "blocks": [{"t": "text", "b": "Up into the tower, mount arrows fore/aft, three new top bolts started. Spreader back in the housing, jack the control arm up and guide the strut's foot fully into the housing until it bottoms on the stop, then a new pinch bolt and nut."}, {"t": "torque", "label": "Upper strut mount bolts (×3)", "nm": 15, "c": {"level": "high", "n": 2, "note": "15 Nm + 90°, new bolts (manufacturer; forum tables agree)."}, "note": "+90° turn"}, {"t": "torque", "label": "Pinch bolt (M14)", "nm": 70, "c": {"level": "high", "n": 2, "note": "70 Nm + 90°, new bolt and nut (manufacturer, forum). The Mk7 figure of 70 + 180° is a different car."}, "note": "+90° turn"}, {"t": "text", "b": "Ball joint back on (60 Nm cast arm, 100 Nm aluminium), CV into the hub, new axle bolt started, level sensor, brake bracket, end link (65 Nm). Other side. Wheels on at 120 Nm; final axle-bolt torque with the car on the ground."}, {"t": "torque", "label": "Outer axle bolt (NEW)", "nm": 200, "alt": [70], "c": {"level": "varies", "n": 2, "note": "Depends on the bolt: hex head or smooth 12-point is 200 Nm + 180°; a ribbed 12-point is 70 Nm + 90°. The owner DIY's '180 or 200' confusion is this. Look at the underside of the bolt head."}, "note": "+180° / +90°"}]}, {"n": 8, "title": "Rear: shock and spring out", "blocks": [{"t": "text", "b": "Driver's side: level-sensor arm nut (10mm). Lower shock bolt (21mm). Two upper shock bolts (13mm on a long extension) and the shock comes down. Jack under the control arm; counter-hold and remove the outer control-arm bolt (18mm both sides), then lower the jack and lift the spring out of its cushion."}]}, {"n": 9, "title": "Rear: build and fit", "blocks": [{"t": "text", "b": "New rear shock: mount (new, or the old one freed with a 16mm and a hex on the rod) onto the rod, upper nut to 25 Nm with a 19mm offset wrench. Rear spring: kit's perch into the top of the spring with the collar wound up (or, on kits with a lower perch, pry the factory lower cushion out of the arm and fit the kit's perch and collar there). Spring into the arm, end coil against its stop, aligned with the body's centring pin."}, {"t": "torque", "label": "Rear shock upper mount bolts (×2)", "nm": 50, "c": {"level": "high", "n": 2, "note": "50 Nm + 45° (manufacturer)."}, "note": "+45° turn"}, {"t": "text", "b": "Shock up and its two upper bolts torqued. Jack the arm until the outer arm bolt slides in; nut on loose. Lower shock bolt in, not torqued."}]}, {"n": 10, "title": "Rear torques at ride height", "caution": true, "blocks": [{"t": "text", "b": "The lower shock bolt and the outer control-arm bolt clamp rubber bushings; torqued in the air they'd be wound up at the wrong angle. Wheels on (120 Nm), lower the car onto its wheels (or onto ramps), then torque both."}, {"t": "torque", "label": "Rear shock lower bolt", "nm": 180, "c": {"level": "high", "n": 2, "note": "180 Nm at ride height (manufacturer). Not the Mk7's 70 + 180°."}}, {"t": "torque", "label": "Rear outer control-arm bolt", "nm": 90, "c": {"level": "high", "n": 2, "note": "90 Nm + 90° at ride height, new bolt."}, "note": "+90° turn"}, {"t": "warn", "b": "On stands, these bolts are just snug. Torque only with the weight on the wheels. Forgetting this is how bushings tear in a month."}]}, {"n": 11, "title": "Set ride height", "blocks": [{"t": "text", "b": "Lift the car so the springs are unloaded (weight off), wind the perches to your target using the measurements from step 1 (a sensible street drop is 1 to 1.5 inches), lower, roll it a few feet, re-measure, repeat. Left and right within a few millimetres. Tighten the front lock rings against the perches. Turn the wheel lock to lock and bounce each corner: nothing touches."}]}, {"n": 12, "title": "Alignment, then re-check", "blocks": [{"t": "text", "b": "Alignment next day, after the springs have settled. Re-measure height after a week; kits settle a few millimetres. Re-check the pinch bolts and end links at 100 miles. Set damping (if adjustable) from the maker's baseline and change one click at a time."}]}], "alsoReplace": [{"name": "Strut mounts and bearings", "why": "They're off the strut (or in the way of it). Notchy steering return and clunks over bumps come from these.", "only": ["reuse"]}, {"name": "Adjustable sway-bar end links", "why": "Lowering shortens the link geometry; adjustable links let the bars sit unloaded at the new height."}, {"name": "Rear shock mounts", "why": "Cheap rubber on a 20-year-old car; they're in your hand."}, {"name": "Camber correction (front camber bolts or plates; rear camber/toe kit)", "why": "Below about 1.5 inches of drop the factory adjustment range runs out and the alignment shop will tell you so."}, {"name": "Front control-arm bushings and dogbone mount", "why": "You've pulled the ball joints; a look at the arm bushings costs nothing, and a worn dogbone shows up more with stiffer suspension."}], "check": {"tab": "How low?", "title": "How low, and how stiff?", "illId": "coilover-hero", "illCap": "Height and damping are separate decisions.", "rows": [{"see": "Daily driver, rough roads", "means": "You want control, not slam.", "do": "1 inch drop, damping at or near the maker's baseline. Bilstein B14, H&R, ST X."}, {"see": "Spirited street, occasional track", "means": "Adjustable damping earns its keep.", "do": "1–1.5 inch, adjustable kit (KW V2/V3, B16, ST XA), adjustable end links, alignment with a little extra negative camber."}, {"see": "Show car", "means": "Looks first.", "do": "Go low, but budget for camber correction, adjustable links and tire wear, and expect the ride to suffer."}], "c": {"level": "community", "n": 4, "note": "Forum consensus; the geometry point is standard suspension practice."}}, "aftercare": ["Alignment after settling.", "Re-torque pinch bolts and end links at 100 miles; re-measure height at a week.", "Grease the threads and lock rings once a year in the salt belt or they seize."], "disagreements": [{"topic": "How hard?", "pos": "Manufacturer: 'Moderate, a couple of hours'. Owners: a full day, more if the pinch bolt fights.", "call": "3.5 out of 5 and a full day."}, {"topic": "Axle bolt torque", "pos": "'180 or 200 Nm depending on which page of Bentley' (owner). Manufacturer table gives three values by bolt type.", "call": "By bolt type. Check the head."}, {"topic": "Brand-specific steps?", "pos": "Brands differ in details.", "call": "The manufacturer guide is explicitly cross-brand and the procedure matches the owner DIYs. The real fork is whether your kit brings its own top mounts, which is the question the guide asks."}], "sources": ["ECS Tuning Mk5/Mk6 coilover installation PDF (2018, cross-brand)", "VWVortex Koni coilover install DIY (part numbers, tools)", "Golfmk7 spring/damper reference (excluded values noted)", "Brand listings: KW, Bilstein, ST, H&R, BC Racing, ECS"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('sway-rear',$j${"id": "sway-rear", "title": "Rear sway bar upgrade", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI · 3.2 R32", "alsoFits": "2006–09 GTI/Rabbit (multilink) · 06–08 Jetta · 06–08 A3 8P FWD · 08+ TT 8J FWD · Mk6 GTI/Golf", "category": "Suspension", "kind": "upgrade", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$200–350", "risk": "Car on jack stands · exhaust clearance", "why": "Your GTI understeers because VW wanted it to. A stiffer rear bar hands some of that grip back to the front, so the car turns in sharper and stays flatter, without touching the ride.", "note": "Manufacturer guides say about 2 hours; owners report closer to 1. Wrestling the bar past the exhaust is the variable."}, "heroCap": "Looking up from under the rear of the car. The bar bolts to the subframe in two brackets and reaches each side through a short end link. Stock is 21.7 mm; upgrades run 24–27 mm.", "should": {"yesIf": ["The car pushes wide (understeers) in fast corners and you'd like it more neutral", "You've done tires and want the next real handling step", "You want a mod you can feel on the first drive", "You'd rather not change springs or dampers yet"], "codes": [], "notes": ["Rear-only is the classic first move on a front-wheel-drive car: the front already has plenty of roll stiffness from doing all the work, so stiffening the rear is what shifts the balance. Upgrading the front too mostly adds flatness, not balance.", "Trade-offs: a stiffer rear bar lifts the inside rear wheel sooner in hard cornering, and mid-corner bumps hit both sides. On all-season tires in the rain, the stiffest setting can make the tail livelier than you want.", "R32: the rear differential sits between the brackets, so there's less room to rotate the bar out; R32-specific bars are sized for the heavier car. Same procedure."], "confidence": {"level": "high", "n": 4, "note": "Consistent across manufacturer descriptions, forum consensus, and basic vehicle dynamics."}}, "parts": [{"tier": "aftermarket", "name": "Rear sway bar kit (bar, bushings, hardware)", "pn": "see options below", "note": "Adjustable (two-hole) bars let you tune it later", "price": "$200–350", "links": []}, {"tier": "oe", "name": "Bracket bolts, M8 (×4)", "pn": "factory", "note": "Torque-to-yield style spec; new ones are cheap", "price": "$8", "links": []}, {"tier": "oe", "name": "End link nuts (×2)", "pn": "factory", "note": "Reusable, but replace if the nylon insert is tired", "price": "$4", "links": []}], "tools": [{"name": "Jack + two jack stands (or ramps)", "note": "final torque happens with the car on its wheels", "price": "$80–150"}, {"name": "10mm triple-square (XZN) bit", "note": "bracket bolts; decent quality, not a bargain-bin set", "price": "$10"}, {"name": "6mm triple-square bit", "note": "holds the end-link stud; it never turns anything", "price": "$8"}, {"name": "16mm wrench + 15mm wrench", "price": "$20"}, {"name": "Torque wrench, 20–60 Nm range", "price": "$40–80"}, {"name": "Poly bushing grease (if the kit's is stingy), tape or towels to protect the bar's finish", "price": "$10"}], "before": ["Level ground, wheels chocked, car in gear or Park. Jack stands on the rear jack points, never the subframe alone.", "Exhaust cold. You'll have your arms around it.", "Check the kit: bar, two bushings, two brackets (if supplied), hardware. Read the kit's sheet; where it gives its own torque values for its own hardware, those win.", "US 2006 GTIs have the multilink rear this guide covers. If your car has a solid beam axle (some base Golfs in other markets), this bar won't fit."], "steps": [{"n": 1, "title": "Raise the rear and support it", "blocks": [{"t": "text", "b": "Jack the rear and set both stands. Wheels can stay on; you're working inboard of them. A creeper or piece of cardboard makes the next hour nicer."}]}, {"n": 2, "title": "Disconnect the end links from the bar", "blocks": [{"t": "text", "b": "Each end of the bar has a short link with a stud through it. Put the 6mm triple-square into the stud's socket to hold it still, and turn the 16mm nut off. There's no room for a ratchet by the caliper; a wrench is fine, the nut isn't very tight."}, {"t": "ill", "id": "endlink", "cap": "The bit only holds the stud. If you try to turn the bit, it strips. Turn the nut."}, {"t": "warn", "b": "The bar is not under load. Nothing springs when the links come off."}]}, {"n": 3, "title": "Swing the bar free of the links", "blocks": [{"t": "text", "b": "Rotate the bar so each end drops out of its link. Leave the links attached to the trailing arms."}]}, {"n": 4, "title": "Unbolt the two brackets", "blocks": [{"t": "text", "b": "Two bolts per bracket into the subframe, 10mm triple-square. Support the bar as the last bolt comes out; it's heavier than it looks."}]}, {"n": 5, "title": "Wrangle the old bar out", "timeSink": true, "blocks": [{"t": "text", "b": "The bar has to rotate around the exhaust to clear. Turn it, tip it, and feed it out one side. If it won't go, loosen the rear muffler hangers (two bolts) to gain an inch of drop."}, {"t": "note", "b": "Pull the old bushings and brackets off it now if you're reusing them. Compare old and new bars side by side; the arm shape should match."}]}, {"n": 6, "title": "Bushings onto the new bar", "blocks": [{"t": "text", "b": "Grease the inside of each bushing with the supplied poly grease (not petroleum grease, which swells polyurethane). Slide them onto the bar at the same positions as the old ones, then set the brackets over them."}, {"t": "note", "b": "Powder coat scratches easily. Leave the plastic wrap on the bar until it's up in the car."}]}, {"n": 7, "title": "Feed the new bar in", "blocks": [{"t": "text", "b": "Reverse of step 5. Get the brackets up to the subframe and start all four bolts by hand. Snug, don't torque, so the bar can still rotate."}]}, {"n": 8, "title": "Pick your setting and connect the links", "blocks": [{"t": "fork", "q": "Which hole?", "v": [{"label": "Forward (softer)", "when": "Start here", "blocks": [{"t": "text", "b": "Roughly double the stock bar's rate on a 25mm bar. A clear step up in turn-in and flatness with no drama. Drive it a week before you decide you want more."}]}, {"label": "Rearward (stiffer)", "when": "Sticky tires, track days", "blocks": [{"t": "text", "b": "About 2.5× stock on a 25mm bar. Sharper still, with more inside-rear wheel lift and a livelier tail in the wet. Common second step, rare first one."}]}]}, {"t": "text", "b": "Rotate the bar so the chosen hole lines up with each end-link stud, pass the stud through, and start the nuts. Snug only."}]}, {"n": 9, "title": "Lower the car, then torque everything", "caution": true, "blocks": [{"t": "text", "b": "The factory manual says these fasteners get their final torque with the car sitting on its wheels, not hanging on stands. Otherwise the bushings and links are clamped at the wrong angle and you get clunks and early bushing wear. Lower onto ramps, or onto the ground and reach under."}, {"t": "torque", "label": "Bracket bolts (M8, ×4) · factory hardware", "nm": 25, "c": {"level": "single", "n": 1, "note": "Bentley manual value via TDIClub: 25 Nm then a further 45° turn. If your kit supplied its own brackets and bolts, use the kit's number (034: 25 Nm flat, with Loctite)."}, "note": "+45° turn"}, {"t": "torque", "label": "End link nuts (M10, ×2)", "nm": 45, "alt": [35], "c": {"level": "varies", "n": 2, "note": "45 Nm is the factory value for factory hardware. 35 Nm is what 034 specifies for its own nylock hardware. Follow whichever hardware you're actually tightening."}}, {"t": "warn", "b": "A forum regular guessed 50 lb-ft (68 Nm) on these and stretched the bolts. Both fasteners are smaller than they feel. Use the wrench."}]}, {"n": 10, "title": "Test drive and re-check", "blocks": [{"t": "text", "b": "Drive 20–50 miles with a few firm corners, then re-torque all six fasteners. Clunking over one-wheel bumps means a bracket or link is loose or the bushing wasn't greased."}]}], "check": {"tab": "Pick a setting", "title": "Which setting is right for you?", "illId": "setting", "illCap": "Both holes are on the same bar. Closer to the pivot is stiffer because the lever is shorter.", "rows": [{"see": "Daily driver, all-season tires", "means": "You want turn-in and less lean, not a tail that steps out in the rain.", "do": "Forward hole. Most people never move it."}, {"see": "Summer tires, spirited driving", "means": "The chassis can use more rear roll stiffness before it gets nervous.", "do": "Start forward, try rearward after a week. Expect more inside-wheel lift."}, {"see": "Autocross or track", "means": "Balance matters more than comfort, and you'll adjust per event.", "do": "Rearward, and consider adjustable end links so both sides preload evenly."}], "c": {"level": "community", "n": 3, "note": "Forum consensus plus manufacturer stiffness figures. There is no factory guidance; this is a preference."}}, "aftercare": ["Re-torque after the first 20–50 miles, then forget about it.", "A squeak on slow speed bumps is a dry bushing. Some brackets have a grease port; otherwise pull the bracket and re-grease.", "Adjustable end links are the usual next step if you go to the stiff hole: they let you remove preload so the bar isn't twisted at rest."], "disagreements": [{"topic": "End link torque", "pos": "45 Nm (factory) vs 35 Nm (034's hardware) vs 55 Nm (Mk7 guides).", "call": "45 for factory hardware, kit value for kit hardware. Mk7 numbers are a different car and excluded."}, {"topic": "Torque on stands or on the ground?", "pos": "Manufacturer PDFs torque on the lift; the factory manual says curb weight.", "call": "Snug in the air, final torque on the wheels."}, {"topic": "Which hole first?", "pos": "“Full stiff rear” vs “start soft.”", "call": "Start soft. It's a two-minute change later."}, {"topic": "Front bar too?", "pos": "Some do both.", "call": "Rear first. On a FWD car it's the balance change; the front is mostly flatness."}], "sources": ["034Motorsport install guide (Mk5/6 FWD)", "Pelican Parts Mk5 GTI rear stabilizer DIY", "TDIClub torque thread citing the Bentley manual", "VWVortex APR 27mm install thread", "GolfMKV H&R 22mm install thread", "Neuspeed product data (stiffness by hole)", "Owner reviews (exhaust clearance, finish)"], "embeds": [{"id": "S8KnvgU-MLQ", "note": "ECS Tuning on a Mk5/Mk6. Same rear subframe and brackets as your car."}, {"id": "2ts5lTilGiM", "note": "034 install and the why-upgrade case"}], "aftermarket": [{"name": "Neuspeed 25mm, adjustable", "note": "Tubular, red, two-hole. Forward hole ≈2× stock, rearward ≈2.5×. The most-recommended bar in Mk5 threads.", "price": "$290", "signal": "Forum favorite", "links": [{"store": "Neuspeed", "url": "https://neuspeed.com/products/neuspeed-anti-sway-bar-rear-25mm-2502253"}]}, {"name": "034Motorsport solid, adjustable", "note": "Solid bar, billet brackets with grease ports, Teflon bushings. Stiffest of the common choices (150%+ over stock).", "price": "$300–350", "signal": "Track-leaning pick", "links": []}, {"name": "H&R 24mm", "note": "Non-adjustable, softer step up. Good if you want less body roll without changing the car's character much.", "price": "$200–250", "signal": "Mild option", "links": []}, {"name": "Whiteline 24mm, adjustable", "note": "Adjustable, well-reviewed, often bundled with their end links.", "price": "$230–280", "signal": "Value pick", "links": []}], "lifespan": {"title": "When owners do this", "headline": ["Usually the first or second handling mod, right after tires"], "earliest": null, "detail": "The stock bar doesn't wear out, so there's no failure mileage. Owners upgrade it when they notice the car pushing wide in fast corners, typically before touching springs or dampers because it's cheaper and reversible.", "factors": ["Sticky summer tires make the understeer more noticeable", "Lowering springs stiffen the front, which increases the case for a rear bar"], "inspect": ["While you're under there: end links and bushings are often tired by 80,000+ miles; replace them if they're loose or cracked"], "confidence": {"level": "community", "n": 4, "note": "Forum consensus on ordering; the end-link mileage is anecdotal."}}, "heroId": "rsbhero"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
